import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test19_executable';

function run(args) {
  try {
    return execFileSync(EXE, args, { encoding: 'utf8', maxBuffer: 1 << 28 });
  } catch (e) {
    return 'ERROR:' + (e.stderr || e.message);
  }
}

function split(out) {
  // returns the 9 blocks using dummy markers
  const lines = out.split('\n');
  return lines;
}

const S = process.argv[2];
const modes = process.argv[3] || 'adef5';

function sect(out, startAfterCount, stopMarker) {
  const lines = out.split('\n');
  let i = 0, seen = 0;
  // skip startAfterCount dummy lines
  const res = [];
  return lines;
}

function extract(out, slot) {
  const lines = out.split('\n');
  const dummies = ['<p>A1</p>', '<p>B1</p>', '<p>C1</p>', '<p>D1</p>', '<p>E1</p>', '<p>F1</p>'];
  // find blocks: walk sequentially; for the slot index, block is between previous dummy and next dummy
  const idx = slot;
  let pos = 0;
  // consume blocks before the slot: each is a single dummy line
  for (let k = 0; k < idx; k++) {
    if (lines[pos] !== dummies[k]) return '<<UNEXPECTED at ' + pos + ': ' + lines[pos] + '>>';
    pos++;
  }
  // now block for slot goes until we see the next dummy (dummies[idx+1]) or, if last, until phase3 start
  let end;
  if (idx < 5) {
    end = pos;
    while (end < lines.length && lines[end] !== dummies[idx + 1]) end++;
  } else {
    end = pos;
    while (end < lines.length && lines[end] !== '<h1>Combined Document</h1>') end++;
  }
  return lines.slice(pos, end).join('\n');
}

function phase5(out) {
  const i = out.lastIndexOf('</article>\n');
  return out.slice(i + '</article>\n'.length);
}

const dummy = ['A1', 'B1', 'C1', 'D1', 'E1', 'F1'];
function argsWith(slot, val) {
  const v = dummy.slice();
  v[slot] = val;
  return ['--a', v[0], '--b', v[1], '--c', v[2], '--d', v[3], '--e', v[4], '--f', v[5]];
}

if (modes.includes('a')) {
  const o = run(argsWith(0, S));
  console.log('===== BASIC (no extensions) =====');
  console.log(extract(o, 0));
}
if (modes.includes('d')) {
  const o = run(argsWith(3, S));
  console.log("===== EXTRA+TABLES =====");
  console.log(extract(o, 3));
}
if (modes.includes('e')) {
  const o = run(argsWith(4, S));
  console.log('===== CODEHILITE+FENCED =====');
  console.log(extract(o, 4));
}
if (modes.includes('f')) {
  const o = run(argsWith(5, S));
  console.log('===== TOC =====');
  console.log(extract(o, 5));
}
if (modes.includes('5')) {
  const o = run(argsWith(0, S));
  console.log('===== ALL/XHTML (phase5, target first then A1..F1 dummies) =====');
  console.log(phase5(o));
}

