/**
 * Character classification helpers.
 *
 * Everything here works on single characters (or code points) using explicit
 * range tables so that no pattern matching machinery is required.
 */

const CP_0 = 48, CP_9 = 57;
const CP_A = 65, CP_Z = 90;
const CP_a = 97, CP_z = 122;
const CP_UNDERSCORE = 95;

/** Python `str.isspace()` / `\s` (unicode) equivalent. */
const SPACE_CODES = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20,
  0x1c, 0x1d, 0x1e, 0x1f, 0x85, 0xa0,
  0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007,
  0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000
]);

export function isSpace(ch) {
  if (ch === undefined || ch === '') return false;
  return SPACE_CODES.has(ch.codePointAt(0));
}

export function isAsciiDigit(ch) {
  if (ch === undefined || ch === '') return false;
  const c = ch.charCodeAt(0);
  return c >= CP_0 && c <= CP_9;
}

export function isAsciiAlpha(ch) {
  if (ch === undefined || ch === '') return false;
  const c = ch.charCodeAt(0);
  return (c >= CP_A && c <= CP_Z) || (c >= CP_a && c <= CP_z);
}

export function isAsciiAlnum(ch) {
  return isAsciiAlpha(ch) || isAsciiDigit(ch);
}

export function isHexDigit(ch) {
  if (ch === undefined || ch === '') return false;
  const c = ch.charCodeAt(0);
  return (c >= CP_0 && c <= CP_9) || (c >= 0x41 && c <= 0x46) || (c >= 0x61 && c <= 0x66);
}

