  [0x0600, 0x0605], [0x060c, 0x060f], [0x061b, 0x061f], [0x066a, 0x066d],
  [0x06d4, 0x06d4],
  [0x0964, 0x0965], [0x0970, 0x0970],
  [0x0e3f, 0x0e3f], [0x0e4f, 0x0e4f], [0x0e5a, 0x0e5b],
  [0x1360, 0x1368], [0x1390, 0x1399],
  [0x1400, 0x1400], [0x166d, 0x166e], [0x169b, 0x169c],
  [0x16eb, 0x16ed], [0x1735, 0x1736], [0x17d4, 0x17d6], [0x17d8, 0x17db],
  [0x1800, 0x180a], [0x1940, 0x1945], [0x19de, 0x19ff],
  [0x1fbd, 0x1fbd], [0x1fbf, 0x1fc1], [0x1fcd, 0x1fcf], [0x1fdd, 0x1fdf],
  [0x1fed, 0x1fef], [0x1ffd, 0x1ffe],
  [0x2000, 0x2064], [0x206a, 0x2070], [0x2074, 0x207e], [0x2080, 0x208e],
  [0x20a0, 0x20cf],
  [0x2100, 0x2101], [0x2103, 0x2106], [0x2108, 0x2109], [0x2114, 0x2114],
  [0x2116, 0x2118], [0x211e, 0x2123], [0x2125, 0x2125], [0x2127, 0x2127],
