/** Python `\w` (unicode) equivalent: letters, digits and underscore. */
export function isWordChar(ch) {
  if (ch === undefined || ch === '') return false;
  const cp = ch.codePointAt(0);
  if (cp < 0x80) {
    return (cp >= CP_0 && cp <= CP_9) || (cp >= CP_A && cp <= CP_Z) ||
      (cp >= CP_a && cp <= CP_z) || cp === CP_UNDERSCORE;
  }
  if (SPACE_CODES.has(cp)) return false;
  if (cp >= 0x2000 && cp <= 0x2bff) return !isLetterLikeException(cp);
  return !inRanges(cp, NON_WORD_RANGES);
}

