  // A few letter-like symbols inside the punctuation/symbol span above.
  return !inRanges(cp, NON_WORD_RANGES);
}

/** True when char is one of the ASCII characters listed in `set`. */
export function inSet(ch, set) {
  return ch !== undefined && ch !== '' && set.indexOf(ch) !== -1;
}

