import { isSpace } from './chars.mjs';

/** Python `str.expandtabs(n)`. */
export function expandTabs(text, tabSize = 4) {
  let out = '';
  let col = 0;
  for (const ch of text) {
    if (ch === '\t') {
      const width = tabSize - (col % tabSize);
      out += ' '.repeat(width);
      col += width;
    } else if (ch === '\n' || ch === '\r') {
      out += ch;
      col = 0;
    } else {
      out += ch;
      col += 1;
    }
  }
  return out;
}

/** Python `str.strip()` (whitespace only). */
export function pyStrip(text) {
  return pyLStrip(pyRStrip(text));
}

export function pyLStrip(text) {
  let i = 0;
  while (i < text.length && isSpace(text[i])) i++;
  return text.slice(i);
}

export function pyRStrip(text) {
  let j = text.length;
  while (j > 0 && isSpace(text[j - 1])) j--;
  return text.slice(0, j);
}

/** Python `str.strip(chars)` for an explicit character set. */
export function stripChars(text, chars) {
  let i = 0, j = text.length;
  while (i < j && chars.indexOf(text[i]) !== -1) i++;
  while (j > i && chars.indexOf(text[j - 1]) !== -1) j--;
  return text.slice(i, j);
}

export function rstripChars(text, chars) {
  let j = text.length;
  while (j > 0 && chars.indexOf(text[j - 1]) !== -1) j--;
  return text.slice(0, j);
}

export function lstripChars(text, chars) {
  let i = 0;
  while (i < text.length && chars.indexOf(text[i]) !== -1) i++;
  return text.slice(i);
}

/** True when the string contains only whitespace (or is empty). */
export function isBlank(text) {
  for (let i = 0; i < text.length; i++) {
    if (!isSpace(text[i])) return false;
  }
  return true;
}

/** Number of leading space characters. */
export function leadingSpaces(line) {
  let i = 0;
  while (i < line.length && line[i] === ' ') i++;
  return i;
}

/** Split on a literal separator (Python `str.split(sep)`). */
export function splitOn(text, sep) {
  return text.split(sep);
}

/** Replace every literal occurrence of `find` by `repl`. */
export function replaceAll(text, find, repl) {
  if (find === '') return text;
  let out = '';
  let pos = 0;
  for (;;) {
    const idx = text.indexOf(find, pos);
    if (idx === -1) {
      out += text.slice(pos);
      return out;
    }
    out += text.slice(pos, idx) + repl;
    pos = idx + find.length;
  }
}

/** Does `text` contain `sub` at position `pos`? */
export function matchAt(text, pos, sub) {
  if (pos < 0 || pos + sub.length > text.length) return false;
  for (let i = 0; i < sub.length; i++) {
    if (text[pos + i] !== sub[i]) return false;
  }
  return true;
}

/** Count of consecutive `ch` starting at `pos`. */
export function runLength(text, pos, ch) {
  let n = 0;
  while (pos + n < text.length && text[pos + n] === ch) n++;
  return n;
}

/** Index of the start of the line containing `pos`. */
export function lineStartIndex(text, pos) {
  const nl = text.lastIndexOf('\n', pos - 1);
  return nl === -1 ? 0 : nl + 1;
}

/**
 * Python's `re.sub(r'(?<=\n) +\n', '\n', text)`: lines consisting only of
 * spaces become truly empty (the first line is never touched because the
 * look-behind requires a preceding newline).
 */
export function blankifyWhitespaceOnlyLines(text) {
  const parts = text.split('\n');
  const out = [parts[0]];
  for (let i = 1; i < parts.length; i++) {
    const part = parts[i];
    if (part.length > 0 && leadingSpaces(part) === part.length) {
      // Only rewritten when a newline follows, i.e. not for the final chunk.
      out.push(i === parts.length - 1 ? part : '');
    } else {
      out.push(part);
    }
  }
  return out.join('\n');
}

/** Zero padded integer, Python `'%04i' % n`. */
export function pad4(n) {
  return String(n).padStart(4, '0');
}

