/**
 * A minimal element tree, modelled on the API surface the reference
 * implementation uses (`text`, `tail`, attribute mapping, child list).
 */

/** Marker class for text which must not be re-processed by inline handling. */
export class AtomicString extends String {}

export function atomic(value) {
  return new AtomicString(value === null || value === undefined ? '' : value);
}

export function isAtomic(value) {
  return value instanceof AtomicString;
}

/** Coerce a text/tail slot to a primitive string (or null). */
export function str(value) {
  if (value === null || value === undefined) return null;
  return value instanceof String ? value.valueOf() : value;
}

/** Same as `str()` but never returns null. */
export function text0(value) {
  const s = str(value);
  return s === null ? '' : s;
}

export const COMMENT = Symbol('comment');
export const PROCESSING_INSTRUCTION = Symbol('pi');

export class Element {
  constructor(tag, attrib) {
    this.tag = tag;
    this.attrib = new Map();
    this.text = null;
    this.tail = null;
    this.children = [];
    if (attrib) {
      for (const [k, v] of Object.entries(attrib)) this.attrib.set(k, v);
    }
  }

  get length() {
    return this.children.length;
  }

  set(key, value) {
    this.attrib.set(key, value);
  }

  get(key, fallback = null) {
    return this.attrib.has(key) ? this.attrib.get(key) : fallback;
  }

  has(key) {
    return this.attrib.has(key);
  }

  items() {
    return [...this.attrib.entries()];
  }

  append(child) {
    this.children.push(child);
  }

  extend(list) {
    for (const c of list) this.children.push(c);
  }

  insert(index, child) {
    this.children.splice(index, 0, child);
  }

  remove(child) {
    const i = this.children.indexOf(child);
    if (i !== -1) this.children.splice(i, 1);
  }

  index(child) {
    return this.children.indexOf(child);
  }

  at(index) {
    return this.children[index < 0 ? this.children.length + index : index];
  }

  /** Depth first iteration over this element and all descendants. */
  *iter(tag = null) {
    if (tag === null || this.tag === tag) yield this;
    for (const child of this.children) {
      if (child instanceof Element) yield* child.iter(tag);
    }
  }

  /** Concatenation of all text content, in document order. */
  *itertext() {
    if (this.text !== null && text0(this.text) !== '') yield this.text;
    for (const child of this.children) {
      yield* child.itertext();
      if (child.tail !== null && text0(child.tail) !== '') yield child.tail;
    }
  }
}

export function subElement(parent, tag, attrib) {
  const el = new Element(tag, attrib);
  parent.append(el);
  return el;
}

