 * Element tree -> HTML/XHTML serialization, including the entity aware
 * escaping rules of the reference implementation.
 */

import { Element, COMMENT, PROCESSING_INSTRUCTION, str, text0 } from './element.mjs';
import { isAsciiAlnum, isAsciiDigit, isHexDigit } from './chars.mjs';

export const HTML_EMPTY = new Set([
  'area', 'base', 'basefont', 'br', 'col', 'embed', 'frame', 'hr', 'img',
  'input', 'isindex', 'link', 'meta', 'param', 'source', 'track', 'wbr'
]);

/**
 * True when the `&` at `pos` opens a character reference
 * (`&#123;`, `&#x1f;` or `&name;`) and therefore must be left alone.
 */
function isEntityStart(text, pos) {
  let i = pos + 1;
  if (i >= text.length) return false;
  if (text[i] === '#') {
    i++;
    if (text[i] === 'x' || text[i] === 'X') {
      i++;
      let n = 0;
      while (i < text.length && isHexDigit(text[i])) { i++; n++; }
      return n > 0 && text[i] === ';';
    }
    let n = 0;
    while (i < text.length && isAsciiDigit(text[i])) { i++; n++; }
    return n > 0 && text[i] === ';';
  }
  let n = 0;
  while (i < text.length && isAsciiAlnum(text[i])) { i++; n++; }
  return n > 0 && text[i] === ';';
}

function escapeAmp(text) {
  if (text.indexOf('&') === -1) return text;
  let out = '';
  for (let i = 0; i < text.length; i++) {
    if (text[i] === '&' && !isEntityStart(text, i)) out += '&amp;';
    else out += text[i];
  }
  return out;
}

export function escapeCdata(value) {
  let text = escapeAmp(text0(value));
  if (text.indexOf('<') !== -1) text = text.split('<').join('&lt;');
  if (text.indexOf('>') !== -1) text = text.split('>').join('&gt;');
  return text;
}

export function escapeAttrib(value) {
  let text = escapeAmp(text0(value));
  if (text.indexOf('<') !== -1) text = text.split('<').join('&lt;');
  if (text.indexOf('>') !== -1) text = text.split('>').join('&gt;');
  if (text.indexOf('"') !== -1) text = text.split('"').join('&quot;');
  if (text.indexOf('\n') !== -1) text = text.split('\n').join('&#10;');
  return text;
}

function compareItems(a, b) {
  if (a[0] < b[0]) return -1;
  if (a[0] > b[0]) return 1;
  if (a[1] < b[1]) return -1;
  if (a[1] > b[1]) return 1;
  return 0;
}

function serialize(out, elem, format) {
  const tag = elem.tag;
  const text = elem.text;
  if (tag === COMMENT) {
    out.push('<!--' + text0(text) + '-->');
  } else if (tag === PROCESSING_INSTRUCTION) {
    out.push('<?' + text0(text) + '?>');
  } else if (tag === null) {
    if (text0(text)) out.push(escapeCdata(text));
    for (const child of elem.children) serialize(out, child, format);
  } else {
    out.push('<' + tag);
    const items = elem.items();
    items.sort(compareItems);
    for (const [k, v] of items) {
      out.push(' ' + k + '="' + escapeAttrib(v) + '"');
    }
    const lower = tag.toLowerCase();
    if (format === 'xhtml' && HTML_EMPTY.has(lower)) {
      out.push(' />');
    } else {
      out.push('>');
      if (text0(text)) {
        if (lower === 'script' || lower === 'style') out.push(text0(text));
        else out.push(escapeCdata(text));
      }
      for (const child of elem.children) serialize(out, child, format);
      if (!HTML_EMPTY.has(lower)) out.push('</' + tag + '>');
    }
  }
  if (text0(elem.tail)) out.push(escapeCdata(elem.tail));
}

export function toHtmlString(element, format = 'xhtml') {
  const out = [];
  serialize(out, element, format);
  return out.join('');
}

