  if (tag === COMMENT) {
    out.push('<!--' + text0(text) + '-->');
  } else if (tag === PROCESSING_INSTRUCTION) {
    out.push('<?' + text0(text) + '?>');
  } else if (tag === null) {
    if (text0(text)) out.push(escapeCdata(text));
    for (const child of elem.children) serialize(out, child, format);
  } else {
    out.push('<' + tag);
    const items = elem.items();
    items.sort(compareItems);
    for (const [k, v] of items) {
      out.push(' ' + k + '="' + escapeAttrib(v) + '"');
    }
    const lower = tag.toLowerCase();
    if (format === 'xhtml' && HTML_EMPTY.has(lower)) {
      out.push(' />');
    } else {
      out.push('>');
      if (text0(text)) {
        if (lower === 'script' || lower === 'style') out.push(text0(text));
        else out.push(escapeCdata(text));
      }
      for (const child of elem.children) serialize(out, child, format);
      if (!HTML_EMPTY.has(lower)) out.push('</' + tag + '>');
    }
  }
  if (text0(elem.tail)) out.push(escapeCdata(elem.tail));
