export class HtmlStash {
  constructor() {
    this.htmlCounter = 0;
    this.rawHtmlBlocks = [];
    this.tagCounter = 0;
    this.tagData = [];
  }

  store(html) {
    this.rawHtmlBlocks.push(html);
    const placeholder = htmlPlaceholder(this.htmlCounter);
    this.htmlCounter += 1;
    return placeholder;
  }

  reset() {
    this.htmlCounter = 0;
    this.rawHtmlBlocks = [];
  }
}

