const NAMED_ENTITIES = new Map(Object.entries({
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
  copy: '©', reg: '®', trade: '™', hellip: '…',
  mdash: '—', ndash: '–', lsquo: '‘', rsquo: '’',
  ldquo: '“', rdquo: '”', laquo: '«', raquo: '»',
  deg: '°', plusmn: '±', times: '×', divide: '÷',
  frac12: '½', sup2: '²', sup3: '³', micro: 'µ',
  para: '¶', middot: '·', bull: '•', dagger: '†',
  euro: '€', pound: '£', yen: '¥', cent: '¢',
  sect: '§', szlig: 'ß', eacute: 'é', egrave: 'è',
  agrave: 'à', ccedil: 'ç', uuml: 'ü', ouml: 'ö',
  auml: 'ä', ntilde: 'ñ', alpha: 'α', beta: 'β',
  gamma: 'γ', delta: 'δ', pi: 'π', sigma: 'σ',
  omega: 'ω', infin: '∞', ne: '≠', le: '≤',
  ge: '≥', larr: '←', rarr: '→', uarr: '↑',
  darr: '↓', harr: '↔', check: '✓', star: '☆'
}));

export function htmlUnescape(text) {
  if (text.indexOf('&') === -1) return text;
  let out = '';
  let i = 0;
  while (i < text.length) {
    if (text[i] !== '&') { out += text[i]; i++; continue; }
    const semi = text.indexOf(';', i + 1);
    if (semi === -1 || semi - i > 32) { out += text[i]; i++; continue; }
    const body = text.slice(i + 1, semi);
    if (body.startsWith('#')) {
      const digits = body.slice(1);
      let code = NaN;
      if (digits[0] === 'x' || digits[0] === 'X') code = parseInt(digits.slice(1), 16);
      else code = /* decimal */ parseIntStrict(digits);
      if (!Number.isNaN(code) && code >= 0 && code <= 0x10ffff) {
        out += String.fromCodePoint(code);
        i = semi + 1;
        continue;
      }
    } else if (NAMED_ENTITIES.has(body)) {
      out += NAMED_ENTITIES.get(body);
      i = semi + 1;
      continue;
    }
    out += text[i];
    i++;
  }
  return out;
}

function parseIntStrict(digits) {
  if (digits.length === 0) return NaN;
  let n = 0;
  for (const ch of digits) {
    const c = ch.charCodeAt(0);
    if (c < 48 || c > 57) return NaN;
    n = n * 10 + (c - 48);
  }
  return n;
}

