  parseStarttag(i) {
    const raw = this.rawdata;
    this.startTagText = null;
    const endpos = this._checkForWholeStartTag(i);
    if (endpos < 0) return endpos;
    this.startTagText = raw.slice(i, endpos);

    let p = i + 1;
    while (p < endpos && TAGNAME_STOP.indexOf(raw[p]) === -1) p++;
    const tag = raw.slice(i + 1, p).toLowerCase();
    while (p < endpos && (isSpace(raw[p]) || (raw[p] === '/' && raw[p + 1] !== '>'))) p++;

