      p++;
      while (p < endpos && !isSpace(raw[p]) && raw[p] !== '/' && raw[p] !== '=' && raw[p] !== '>') p++;
      const name = raw.slice(nameStart, p).toLowerCase();
      let value = null;
      let q = p;
      while (q < endpos && isSpace(raw[q])) q++;
      if (q < endpos && raw[q] === '=') {
        while (q < endpos && raw[q] === '=') q++;
        while (q < endpos && isSpace(raw[q])) q++;
        if (raw[q] === '"' || raw[q] === "'") {
          const quote = raw[q];
          const close = raw.indexOf(quote, q + 1);
          if (close === -1 || close >= endpos) { value = raw.slice(q + 1, endpos); q = endpos; }
          else { value = raw.slice(q + 1, close); q = close + 1; }
        } else {
          const vStart = q;
          while (q < endpos && !isSpace(raw[q]) && raw[q] !== '>') q++;
