    const end = pyStrip(raw.slice(p, endpos));
    if (end !== '>' && end !== '/>') {
      this.handleData(raw.slice(i, endpos));
      return endpos;
    }
    if (end.endsWith('/>')) {
      this.handleStartendtag(tag, attrs);
    } else {
      this.handleStarttag(tag, attrs);
      if (CDATA_CONTENT_ELEMENTS.has(tag)) this.setCdataMode(tag);
    }
    return endpos;
  }

  parseEndtag(i) {
    const raw = this.rawdata;
    const gt = raw.indexOf('>', i + 1);
    if (gt === -1) return -1;
    let gtpos = gt + 1;

    // `</` optional space, tag name, optional space, `>`
    let p = i + 2;
    while (p < raw.length && isSpace(raw[p])) p++;
    let strict = isAsciiAlpha(raw[p]);
    let nameEnd = p;
    if (strict) {
      nameEnd = p + 1;
      while (nameEnd < raw.length && (isAsciiAlpha(raw[nameEnd]) || isAsciiDigit(raw[nameEnd]) ||
        '-.:_'.indexOf(raw[nameEnd]) !== -1)) nameEnd++;
      let q = nameEnd;
      while (q < raw.length && isSpace(raw[q])) q++;
      if (raw[q] !== '>') strict = false;
      else gtpos = q + 1;
    }

    if (!strict) {
      if (this.cdataElem !== null) {
        this.handleData(raw.slice(i, gtpos));
        return gtpos;
      }
      let t = i + 2;
      if (!isAsciiAlpha(raw[t])) {
        if (matchAt(raw, i, '</>')) return i + 3;
        return this.parseBogusComment(i);
      }
      let te = t;
      while (te < raw.length && TAGNAME_STOP.indexOf(raw[te]) === -1) te++;
      const tagname = raw.slice(t, te).toLowerCase();
      const close = raw.indexOf('>', te);
      this.handleEndtag(tagname);
      return close + 1;
    }

    const elem = raw.slice(p, nameEnd).toLowerCase();
    if (this.cdataElem !== null && elem !== this.cdataElem) {
      this.handleData(raw.slice(i, gtpos));
      return gtpos;
    }
    this.handleEndtag(elem);
    this.clearCdataMode();
    return gtpos;
  }

  parseComment(i) {
    const raw = this.rawdata;
    // Closing sequence is `--`, optional whitespace, `>`.
    let p = i + 4;
    for (;;) {
      const dash = raw.indexOf('--', p);
      if (dash === -1) return -1;
      let q = dash + 2;
      while (q < raw.length && isSpace(raw[q])) q++;
      if (raw[q] === '>') {
        this.handleComment(raw.slice(i + 4, dash));
        return q + 1;
      }
      p = dash + 1;
    }
  }

  parsePi(i) {
    const raw = this.rawdata;
    const close = raw.indexOf('?>', i + 2);
    if (close === -1) return -1;
    this.handlePi(raw.slice(i + 2, close));
    return close + 2;
  }

  parseHtmlDeclaration(i) {
    const raw = this.rawdata;
    if (matchAt(raw, i, '<!--')) return this.parseComment(i);
    if (matchAt(raw, i, '<![')) return this.parseMarkedSection(i);
    if (raw.slice(i, i + 9).toLowerCase() === '<!doctype') {
      const gt = raw.indexOf('>', i + 9);
      if (gt === -1) return -1;
      this.handleDecl(raw.slice(i + 2, gt));
      return gt + 1;
    }
    return this.parseBogusComment(i);
  }

  parseBogusComment(i) {
    const raw = this.rawdata;
    const gt = raw.indexOf('>', i + 2);
    if (gt === -1) return -1;
    this.handleComment(raw.slice(i + 2, gt));
    return gt + 1;
  }

  parseMarkedSection(i) {
    const raw = this.rawdata;
    const rest = raw.slice(i + 3);
    if (rest.startsWith('CDATA[')) {
      const close = raw.indexOf(']]>', i + 3);
      if (close === -1) return -1;
      this.unknownDecl(raw.slice(i + 3, close));
      return close + 3;
    }
    const close = raw.indexOf(']>', i + 3);
    if (close === -1) return -1;
    this.unknownDecl(raw.slice(i + 3, close));
    return close + 2;
  }
}

/** Two consecutive newlines (with optional leading spaces) at `pos`. */
function blankLineAt(text, pos) {
  let p = pos;
  for (let line = 0; line < 2; line++) {
    let q = p;
    while (q < text.length && text[q] === ' ') q++;
    if (text[q] !== '\n') return false;
    p = q + 1;
  }
  return true;
}

/**
 * Pull raw HTML out of a document, storing it in the markdown instance's
 * stash and leaving placeholders behind.
 */
export class HTMLExtractor extends HTMLTokenizer {
  constructor(md) {
    super();
    this.md = md;
    this.emptyTags = new Set(['hr']);
    this.inraw = false;
    this.intail = false;
    this.stack = [];
    this._cache = [];
    this.cleandoc = [];
  }

  close() {
    if (this._cache.length) {
      this.cleandoc.push(this.md.htmlStash.store(this._cache.join('')));
      this._cache = [];
    }
  }

  atLineStart() {
    const offset = this.offset;
    if (offset === 0) return true;
    if (offset > 3) return false;
    return isBlank(this.rawdata.slice(this.lineOffset, this.lineOffset + offset));
  }

  getEndtagText(tag) {
    const start = this.pos;
    const gt = this.rawdata.indexOf('>', start);
    if (gt !== -1) return this.rawdata.slice(start, gt + 1);
    return '</' + tag + '>';
  }

  handleStarttag(tag, attrs) {
    if (this.emptyTags.has(tag)) {
      this.handleStartendtag(tag, attrs);
      return;
    }
    if (this.md.isBlockLevel(tag) && (this.intail || (this.atLineStart() && !this.inraw))) {
      this.inraw = true;
      this.cleandoc.push('\n');
    }
    const text = this.getStarttagText();
    if (this.inraw) {
      this.stack.push(tag);
      this._cache.push(text);
    } else {
      this.cleandoc.push(text);
      if (CDATA_CONTENT_ELEMENTS.has(tag)) this.clearCdataMode();
    }
  }

  handleEndtag(tag) {
    const text = this.getEndtagText(tag);
    if (this.inraw) {
      this.stack.pop();
      if (this.stack.length === 0) {
        if (blankLineAt(this.rawdata, this.pos + text.length)) {
          this._cache.push('\n');
        } else {
          this.intail = true;
        }
        this.inraw = false;
        this._cache.push(text);
        this.cleandoc.push(this.md.htmlStash.store(this._cache.join('')));
        this.cleandoc.push('\n\n');
        this._cache = [];
      } else {
        this._cache.push(text);
      }
    } else {
      this.cleandoc.push(text);
    }
  }

  handleData(data) {
    if (this.intail && data.indexOf('\n') !== -1) this.intail = false;
    if (this.inraw) this._cache.push(data);
    else this.cleandoc.push(data);
  }

  handleEmptyTag(data, isBlock) {
    if (this.inraw || this.intail) {
      this._cache.push(data);
      return;
    }
    if (this.atLineStart() && isBlock) {
      let payload = data;
      if (blankLineAt(this.rawdata, this.pos + data.length)) payload = data + '\n';
      else this.intail = true;
      const item = this.cleandoc.length ? this.cleandoc[this.cleandoc.length - 1] : '';
      if (typeof item === 'string' && !item.endsWith('\n\n') && item.endsWith('\n')) {
        this.cleandoc.push('\n');
      }
      this.cleandoc.push(this.md.htmlStash.store(payload));
      this.cleandoc.push('\n\n');
    } else {
      this.cleandoc.push(data);
    }
  }

  handleStartendtag(tag, attrs) {
    this.handleEmptyTag(this.getStarttagText(), this.md.isBlockLevel(tag));
  }

  handleCharref(name) {
    this.handleEmptyTag('&#' + name + ';', false);
  }

  handleEntityref(name) {
    this.handleEmptyTag('&' + name + ';', false);
  }

  handleComment(data) {
    this.handleEmptyTag('<!--' + data + '-->', true);
  }

  handleDecl(data) {
    this.handleEmptyTag('<!' + data + '>', true);
  }

  handlePi(data) {
    this.handleEmptyTag('<?' + data + '?>', true);
  }

  unknownDecl(data) {
    const end = data.startsWith('CDATA[') ? ']]>' : ']>';
    this.handleEmptyTag('<![' + data + end, true);
  }
}

export { leadingSpaces };

