/**
 * A tokenizer compatible with the HTML parser used by the reference
 * implementation, plus the extractor that pulls raw HTML blocks out of a
 * markdown document and replaces them with stash placeholders.
 *
 * The tokenizer is a hand written scanner: it walks the source character by
 * character reproducing the state machine of the original parser (start tags,
 * end tags, comments, processing instructions, declarations, marked sections,
 * character references and CDATA elements such as `script`/`style`).
 */

import { isAsciiAlpha, isAsciiDigit, isHexDigit, isSpace } from './chars.mjs';
import { isBlank, leadingSpaces, matchAt, pyStrip } from './strings.mjs';
import { htmlUnescape } from './util.mjs';

const CDATA_CONTENT_ELEMENTS = new Set(['script', 'style']);
const TAGNAME_STOP = '\t\n\r\f />�';
const ATTR_LOOKBEHIND = '\'" \t\n\r\f/\v';

/** Base tokenizer. Subclasses override the `handle*` hooks. */
export class HTMLTokenizer {
  constructor() {
    this.rawdata = '';
    this.cdataElem = null;
    this.pos = 0;
    this.startTagText = null;
  }

  feed(data) {
    this.rawdata += data;
    this.goahead();
  }

  close() {}

  /* ------------------------------------------------------------------ hooks */
  handleStarttag(tag, attrs) {}
  handleEndtag(tag) {}
  handleStartendtag(tag, attrs) { this.handleStarttag(tag, attrs); this.handleEndtag(tag); }
  handleData(data) {}
  handleComment(data) {}
  handleDecl(data) {}
  handlePi(data) {}
  handleCharref(name) {}
  handleEntityref(name) {}
  unknownDecl(data) {}

  getStarttagText() {
    return this.startTagText;
  }

  /* ------------------------------------------------------------- positions */
  get lineOffset() {
    const nl = this.rawdata.lastIndexOf('\n', this.pos - 1);
    return nl === -1 ? 0 : nl + 1;
  }

  get offset() {
    return this.pos - this.lineOffset;
  }

  /* -------------------------------------------------------------- scanning */
  setCdataMode(tag) {
    this.cdataElem = tag.toLowerCase();
  }

  clearCdataMode() {
    this.cdataElem = null;
  }

  /** Index of the next `<` or `&` (or of `</tag` while in CDATA mode). */
  _findInteresting(from) {
    const raw = this.rawdata;
    if (this.cdataElem !== null) {
      let i = from;
      for (;;) {
        i = raw.indexOf('</', i);
        if (i === -1) return -1;
        let j = i + 2;
        while (j < raw.length && isSpace(raw[j])) j++;
        if (raw.slice(j, j + this.cdataElem.length).toLowerCase() === this.cdataElem) return i;
        i += 2;
      }
    }
    let best = -1;
    const lt = raw.indexOf('<', from);
    const amp = raw.indexOf('&', from);
    if (lt === -1) best = amp;
    else if (amp === -1) best = lt;
    else best = Math.min(lt, amp);
    return best;
  }

  goahead() {
    const raw = this.rawdata;
    const n = raw.length;
    let i = 0;
    while (i < n) {
      let j = this._findInteresting(i);
      if (j === -1) {
        if (this.cdataElem !== null) break;
        j = n;
      }
      if (i < j) {
        this.pos = i;
        this.handleData(raw.slice(i, j));
      }
      i = j;
      if (i === n) break;
      let k;
      if (raw[i] === '<') {
        this.pos = i;
        if (isAsciiAlpha(raw[i + 1])) k = this.parseStarttag(i);
        else if (matchAt(raw, i, '</')) k = this.parseEndtag(i);
        else if (matchAt(raw, i, '<!--')) k = this.parseComment(i);
        else if (matchAt(raw, i, '<?')) k = this.parsePi(i);
        else if (matchAt(raw, i, '<!')) k = this.parseHtmlDeclaration(i);
        else { this.handleData('<'); k = i + 1; }
        if (k < 0) {
          k = raw.indexOf('>', i + 1);
          if (k < 0) {
            k = raw.indexOf('<', i + 1);
            if (k < 0) k = i + 1;
          } else {
            k += 1;
          }
          this.pos = i;
          this.handleData(raw.slice(i, k));
        }
        i = k;
      } else if (matchAt(raw, i, '&#')) {
        const m = this._matchCharref(i);
        if (m !== -1) {
          this.pos = i;
          let end = m;
          const name = raw.slice(i + 2, end - 1);
          this.handleCharref(name);
          if (raw[end - 1] !== ';') end -= 1;
          i = end;
          continue;
        }
        if (raw.indexOf(';', i) !== -1) {
          this.pos = i;
          this.handleData(raw.slice(i, i + 2));
          i += 2;
        }
        break;
      } else {
        const m = this._matchEntityref(i);
        if (m !== -1) {
          this.pos = i;
          this.handleEntityref(raw.slice(i + 1, m - 1));
          i = m;
          continue;
        }
        if (i + 1 < n) {
          this.pos = i;
          this.handleData('&');
          i += 1;
        } else {
          break;
        }
      }
    }
    if (i < n) {
      this.pos = i;
      this.handleData(raw.slice(i, n));
      i = n;
    }
    this.rawdata = raw.slice(i);
  }

  /** `&#123;` / `&#x1F;` -> index just past the reference, else -1. */
  _matchCharref(i) {
    const raw = this.rawdata;
    let p = i + 2;
    if (raw[p] === 'x' || raw[p] === 'X') {
      p++;
      let count = 0;
      while (p < raw.length && isHexDigit(raw[p])) { p++; count++; }
      if (count === 0) return -1;
    } else {
      let count = 0;
      while (p < raw.length && isAsciiDigit(raw[p])) { p++; count++; }
      if (count === 0) return -1;
    }
    // The original pattern requires one trailing non hex-digit character.
    if (p >= raw.length) return -1;
    return p + 1;
  }

  /** `&name;` -> index just past the `;`, else -1. */
  _matchEntityref(i) {
    const raw = this.rawdata;
    let p = i + 1;
    if (!isAsciiAlpha(raw[p])) return -1;
    p++;
    while (p < raw.length && (isAsciiAlpha(raw[p]) || isAsciiDigit(raw[p]) ||
      raw[p] === '-' || raw[p] === '.')) p++;
    if (raw[p] !== ';') return -1;
    return p + 1;
  }

  /** End of the start tag "body" (everything before `>` or `/>`). */
  _locateStarttagEnd(i) {
    const raw = this.rawdata;
    const n = raw.length;
    let p = i + 1;
    while (p < n && TAGNAME_STOP.indexOf(raw[p]) === -1) p++;
    let q = p;
    while (q < n && (isSpace(raw[q]) || raw[q] === '/')) q++;
    for (;;) {
      if (q >= n) break;
      const prev = q > 0 ? raw[q - 1] : '';
      if (ATTR_LOOKBEHIND.indexOf(prev) === -1) break;
      if (isSpace(raw[q]) || raw[q] === '/' || raw[q] === '>') break;
      // attribute name
      q++;
      while (q < n && !isSpace(raw[q]) && raw[q] !== '/' && raw[q] !== '=' && raw[q] !== '>') q++;
      // optional value
      let r = q;
      while (r < n && isSpace(raw[r])) r++;
      if (r < n && raw[r] === '=') {
        while (r < n && raw[r] === '=') r++;
        while (r < n && isSpace(raw[r])) r++;
        if (raw[r] === '"' || raw[r] === "'") {
          const quote = raw[r];
          const close = raw.indexOf(quote, r + 1);
          if (close === -1) break;
          r = close + 1;
        } else {
          while (r < n && !isSpace(raw[r]) && raw[r] !== '>') r++;
        }
        for (;;) {
          let s = r;
          while (s < n && isSpace(raw[s])) s++;
          if (raw[s] === ',') r = s + 1;
          else break;
        }
        q = r;
      }
      while (q < n && (isSpace(raw[q]) || (raw[q] === '/' && raw[q + 1] !== '>'))) q++;
    }
    while (q < n && isSpace(raw[q])) q++;
    return q;
  }

  _checkForWholeStartTag(i) {
    const raw = this.rawdata;
    const j = this._locateStarttagEnd(i);
    const next = j < raw.length ? raw[j] : '';
    if (next === '>') return j + 1;
    if (next === '/') {
      if (matchAt(raw, j, '/>')) return j + 2;
      return -1;
    }
    if (next === '') return -1;
    if (isAsciiAlpha(next) || next === '=') return -1;
    return j > i ? j : i + 1;
  }

  parseStarttag(i) {
    const raw = this.rawdata;
    this.startTagText = null;
    const endpos = this._checkForWholeStartTag(i);
    if (endpos < 0) return endpos;
    this.startTagText = raw.slice(i, endpos);

    let p = i + 1;
    while (p < endpos && TAGNAME_STOP.indexOf(raw[p]) === -1) p++;
    const tag = raw.slice(i + 1, p).toLowerCase();
    while (p < endpos && (isSpace(raw[p]) || (raw[p] === '/' && raw[p + 1] !== '>'))) p++;

    const attrs = [];
    while (p < endpos) {
      if (isSpace(raw[p]) || raw[p] === '/' || raw[p] === '>') break;
      const nameStart = p;
      p++;
      while (p < endpos && !isSpace(raw[p]) && raw[p] !== '/' && raw[p] !== '=' && raw[p] !== '>') p++;
      const name = raw.slice(nameStart, p).toLowerCase();
      let value = null;
      let q = p;
      while (q < endpos && isSpace(raw[q])) q++;
      if (q < endpos && raw[q] === '=') {
        while (q < endpos && raw[q] === '=') q++;
        while (q < endpos && isSpace(raw[q])) q++;
        if (raw[q] === '"' || raw[q] === "'") {
          const quote = raw[q];
          const close = raw.indexOf(quote, q + 1);
          if (close === -1 || close >= endpos) { value = raw.slice(q + 1, endpos); q = endpos; }
          else { value = raw.slice(q + 1, close); q = close + 1; }
        } else {
          const vStart = q;
          while (q < endpos && !isSpace(raw[q]) && raw[q] !== '>') q++;
          value = raw.slice(vStart, q);
        }
        if (value) value = htmlUnescape(value);
        p = q;
      }
      attrs.push([name, value]);
      while (p < endpos && (isSpace(raw[p]) || (raw[p] === '/' && raw[p + 1] !== '>'))) p++;
    }

    const end = pyStrip(raw.slice(p, endpos));
    if (end !== '>' && end !== '/>') {
      this.handleData(raw.slice(i, endpos));
      return endpos;
    }
    if (end.endsWith('/>')) {
      this.handleStartendtag(tag, attrs);
    } else {
      this.handleStarttag(tag, attrs);
      if (CDATA_CONTENT_ELEMENTS.has(tag)) this.setCdataMode(tag);
    }
    return endpos;
  }

  parseEndtag(i) {
    const raw = this.rawdata;
    const gt = raw.indexOf('>', i + 1);
    if (gt === -1) return -1;
    let gtpos = gt + 1;

    // `</` optional space, tag name, optional space, `>`
    let p = i + 2;
    while (p < raw.length && isSpace(raw[p])) p++;
    let strict = isAsciiAlpha(raw[p]);
    let nameEnd = p;
    if (strict) {
      nameEnd = p + 1;
      while (nameEnd < raw.length && (isAsciiAlpha(raw[nameEnd]) || isAsciiDigit(raw[nameEnd]) ||
        '-.:_'.indexOf(raw[nameEnd]) !== -1)) nameEnd++;
      let q = nameEnd;
      while (q < raw.length && isSpace(raw[q])) q++;
      if (raw[q] !== '>') strict = false;
      else gtpos = q + 1;
    }

    if (!strict) {
      if (this.cdataElem !== null) {
        this.handleData(raw.slice(i, gtpos));
        return gtpos;
      }
      let t = i + 2;
      if (!isAsciiAlpha(raw[t])) {
        if (matchAt(raw, i, '</>')) return i + 3;
        return this.parseBogusComment(i);
      }
      let te = t;
      while (te < raw.length && TAGNAME_STOP.indexOf(raw[te]) === -1) te++;
      const tagname = raw.slice(t, te).toLowerCase();
      const close = raw.indexOf('>', te);
      this.handleEndtag(tagname);
      return close + 1;
    }

    const elem = raw.slice(p, nameEnd).toLowerCase();
    if (this.cdataElem !== null && elem !== this.cdataElem) {
      this.handleData(raw.slice(i, gtpos));
      return gtpos;
    }
    this.handleEndtag(elem);
    this.clearCdataMode();
    return gtpos;
  }

  parseComment(i) {
    const raw = this.rawdata;
    // Closing sequence is `--`, optional whitespace, `>`.
    let p = i + 4;
    for (;;) {
      const dash = raw.indexOf('--', p);
      if (dash === -1) return -1;
      let q = dash + 2;
      while (q < raw.length && isSpace(raw[q])) q++;
      if (raw[q] === '>') {
        this.handleComment(raw.slice(i + 4, dash));
        return q + 1;
      }
      p = dash + 1;
    }
  }

  parsePi(i) {
    const raw = this.rawdata;
    const close = raw.indexOf('?>', i + 2);
    if (close === -1) return -1;
    this.handlePi(raw.slice(i + 2, close));
    return close + 2;
  }

  parseHtmlDeclaration(i) {
    const raw = this.rawdata;
    if (matchAt(raw, i, '<!--')) return this.parseComment(i);
    if (matchAt(raw, i, '<![')) return this.parseMarkedSection(i);
    if (raw.slice(i, i + 9).toLowerCase() === '<!doctype') {
      const gt = raw.indexOf('>', i + 9);
      if (gt === -1) return -1;
      this.handleDecl(raw.slice(i + 2, gt));
      return gt + 1;
    }
    return this.parseBogusComment(i);
  }

  parseBogusComment(i) {
    const raw = this.rawdata;
    const gt = raw.indexOf('>', i + 2);
    if (gt === -1) return -1;
    this.handleComment(raw.slice(i + 2, gt));
    return gt + 1;
  }

  parseMarkedSection(i) {
    const raw = this.rawdata;
    const rest = raw.slice(i + 3);
    if (rest.startsWith('CDATA[')) {
      const close = raw.indexOf(']]>', i + 3);
      if (close === -1) return -1;
      this.unknownDecl(raw.slice(i + 3, close));
      return close + 3;
    }
    const close = raw.indexOf(']>', i + 3);
    if (close === -1) return -1;
    this.unknownDecl(raw.slice(i + 3, close));
    return close + 2;
  }
}

/** Two consecutive newlines (with optional leading spaces) at `pos`. */
function blankLineAt(text, pos) {
  let p = pos;
  for (let line = 0; line < 2; line++) {
    let q = p;
    while (q < text.length && text[q] === ' ') q++;
    if (text[q] !== '\n') return false;
    p = q + 1;
  }
  return true;
}

/**
 * Pull raw HTML out of a document, storing it in the markdown instance's
 * stash and leaving placeholders behind.
 */
export class HTMLExtractor extends HTMLTokenizer {
  constructor(md) {
    super();
    this.md = md;
    this.emptyTags = new Set(['hr']);
    this.inraw = false;
    this.intail = false;
    this.stack = [];
    this._cache = [];
    this.cleandoc = [];
  }

  close() {
    if (this._cache.length) {
      this.cleandoc.push(this.md.htmlStash.store(this._cache.join('')));
      this._cache = [];
    }
  }

  atLineStart() {
    const offset = this.offset;
    if (offset === 0) return true;
    if (offset > 3) return false;
    return isBlank(this.rawdata.slice(this.lineOffset, this.lineOffset + offset));
  }

  getEndtagText(tag) {
    const start = this.pos;
    const gt = this.rawdata.indexOf('>', start);
    if (gt !== -1) return this.rawdata.slice(start, gt + 1);
    return '</' + tag + '>';
  }

  handleStarttag(tag, attrs) {
    if (this.emptyTags.has(tag)) {
      this.handleStartendtag(tag, attrs);
      return;
    }
    if (this.md.isBlockLevel(tag) && (this.intail || (this.atLineStart() && !this.inraw))) {
      this.inraw = true;
      this.cleandoc.push('\n');
    }
    const text = this.getStarttagText();
    if (this.inraw) {
      this.stack.push(tag);
      this._cache.push(text);
    } else {
      this.cleandoc.push(text);
      if (CDATA_CONTENT_ELEMENTS.has(tag)) this.clearCdataMode();
    }
  }

  handleEndtag(tag) {
    const text = this.getEndtagText(tag);
    if (this.inraw) {
      this.stack.pop();
      if (this.stack.length === 0) {
        if (blankLineAt(this.rawdata, this.pos + text.length)) {
          this._cache.push('\n');
        } else {
          this.intail = true;
        }
        this.inraw = false;
        this._cache.push(text);
        this.cleandoc.push(this.md.htmlStash.store(this._cache.join('')));
        this.cleandoc.push('\n\n');
        this._cache = [];
      } else {
        this._cache.push(text);
      }
    } else {
      this.cleandoc.push(text);
    }
  }

  handleData(data) {
    if (this.intail && data.indexOf('\n') !== -1) this.intail = false;
    if (this.inraw) this._cache.push(data);
    else this.cleandoc.push(data);
  }

  handleEmptyTag(data, isBlock) {
    if (this.inraw || this.intail) {
      this._cache.push(data);
      return;
    }
    if (this.atLineStart() && isBlock) {
      let payload = data;
      if (blankLineAt(this.rawdata, this.pos + data.length)) payload = data + '\n';
      else this.intail = true;
      const item = this.cleandoc.length ? this.cleandoc[this.cleandoc.length - 1] : '';
      if (typeof item === 'string' && !item.endsWith('\n\n') && item.endsWith('\n')) {
        this.cleandoc.push('\n');
      }
      this.cleandoc.push(this.md.htmlStash.store(payload));
      this.cleandoc.push('\n\n');
    } else {
      this.cleandoc.push(data);
    }
  }

  handleStartendtag(tag, attrs) {
    this.handleEmptyTag(this.getStarttagText(), this.md.isBlockLevel(tag));
  }

  handleCharref(name) {
    this.handleEmptyTag('&#' + name + ';', false);
  }

  handleEntityref(name) {
    this.handleEmptyTag('&' + name + ';', false);
  }

  handleComment(data) {
    this.handleEmptyTag('<!--' + data + '-->', true);
  }

  handleDecl(data) {
    this.handleEmptyTag('<!' + data + '>', true);
  }

  handlePi(data) {
    this.handleEmptyTag('<?' + data + '?>', true);
  }

  unknownDecl(data) {
    const end = data.startsWith('CDATA[') ? ']]>' : ']>';
    this.handleEmptyTag('<![' + data + end, true);
  }
}

export { leadingSpaces };

