/**
 * The block level parser: it consumes a document, splits it into blocks and
 * lets the registered block processors build the element tree.
 */

import { Element } from './element.mjs';
import { Registry } from './util.mjs';

/** A simple stack of parser states (`list`, `looselist`, `detabbed`, ...). */
export class State {
  constructor() {
    this.stack = [];
  }

  set(state) {
    this.stack.push(state);
  }

  reset() {
    this.stack.pop();
  }

  isstate(state) {
    return this.stack.length > 0 && this.stack[this.stack.length - 1] === state;
  }
}

export class BlockParser {
  constructor(md) {
    this.blockprocessors = new Registry();
    this.state = new State();
    this.md = md;
  }

  parseDocument(lines) {
    this.root = new Element(this.md.docTag);
    this.parseChunk(this.root, lines.join('\n'));
    return this.root;
  }

  parseChunk(parent, text) {
    this.parseBlocks(parent, text.split('\n\n'));
  }

  parseBlocks(parent, blocks) {
    while (blocks.length) {
      for (const processor of this.blockprocessors) {
        if (processor.test(parent, blocks[0])) {
          if (processor.run(parent, blocks) !== false) break;
        }
      }
    }
  }
}

/** Common helpers shared by every block processor. */
export class BlockProcessor {
  constructor(parser) {
    this.parser = parser;
    this.tabLength = parser.md.tabLength;
  }

  lastChild(parent) {
    return parent.length ? parent.at(-1) : null;
  }

  /** Strip one indentation level, returning `[block, theRest]`. */
  detab(text, length = null) {
    const width = length === null ? this.tabLength : length;
    const pad = ' '.repeat(width);
    const lines = text.split('\n');
    const newtext = [];
    for (const line of lines) {
      if (line.startsWith(pad)) newtext.push(line.slice(width));
      else if (line.trim() === '') newtext.push('');
      else break;
    }
    return [newtext.join('\n'), lines.slice(newtext.length).join('\n')];
  }

  /** Strip indentation where present, leaving dedented lines untouched. */
  looseDetab(text, level = 1) {
    const width = this.tabLength * level;
    const pad = ' '.repeat(width);
    const lines = text.split('\n');
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].startsWith(pad)) lines[i] = lines[i].slice(width);
    }
    return lines.join('\n');
  }

  test(parent, block) {
    return false;
  }

  run(parent, blocks) {}
}

