/**
 * The default block processors: code blocks, headers, rules, lists, quotes,
 * link references and paragraphs.
 *
 * Every pattern used by the reference implementation is expressed here as an
 * explicit scanner so the matching semantics (lazy vs greedy, anchoring,
 * multiline behaviour) stay observable and identical.
 */

import { BlockProcessor } from './blockparser.mjs';
import { Element, atomic, subElement, text0 } from './element.mjs';
import { isAsciiDigit, isSpace } from './chars.mjs';
import { isBlank, leadingSpaces, matchAt, pyStrip, pyLStrip, pyRStrip, rstripChars, lstripChars } from './strings.mjs';

/** HTML escape used for code content. */
export function codeEscape(text) {
  let out = text;
  if (out.indexOf('&') !== -1) out = out.split('&').join('&amp;');
  if (out.indexOf('<') !== -1) out = out.split('<').join('&lt;');
  if (out.indexOf('>') !== -1) out = out.split('>').join('&gt;');
  return out;
}

/* --------------------------------------------------------------- scanners */

/** All indices at which a line starts. */
function lineStarts(text) {
  const starts = [0];
  let i = text.indexOf('\n');
  while (i !== -1) {
    starts.push(i + 1);
    i = text.indexOf('\n', i + 1);
  }
  return starts;
}

/** Index of the end of the line containing `pos` (exclusive of `\n`). */
function lineEnd(text, pos) {
  const i = text.indexOf('\n', pos);
  return i === -1 ? text.length : i;
}

/**
 * `(?:^|\n)(#{1,6})((?:\\.|[^\\])*?)#*(?:\n|$)`
 * Returns `{start, end, level, header}` or null.
 */
export function findHashHeader(block) {
  for (const start of lineStarts(block)) {
    let p = start;
    let level = 0;
    while (level < 6 && block[p + level] === '#') level++;
    if (level === 0) continue;
    let j = p + level;
    for (;;) {
      // Try to terminate the (lazy) header text here.
      let k = j;
      while (block[k] === '#') k++;
      if (k >= block.length) {
        return { start, end: block.length, level, header: block.slice(p + level, j) };
      }
      if (block[k] === '\n') {
        return { start, end: k + 1, level, header: block.slice(p + level, j) };
      }
      // Otherwise consume one more character of header text.
      if (block[j] === '\\') {
        if (j + 1 >= block.length || block[j + 1] === '\n') break;
        j += 2;
      } else if (j >= block.length) {
        break;
      } else {
        j += 1;
      }
    }
  }
  return null;
}

/** `^.*?\n[=-]+[ ]*(\n|$)` anchored at position 0. */
export function matchSetextHeader(block) {
  const nl = block.indexOf('\n');
  if (nl === -1) return false;
  let p = nl + 1;
  let count = 0;
  while (p < block.length && (block[p] === '=' || block[p] === '-')) { p++; count++; }
  if (count === 0) return false;
  while (p < block.length && block[p] === ' ') p++;
  return p >= block.length || block[p] === '\n';
}

/**
 * Horizontal rule: `^[ ]{0,3}((c+[ ]{0,2}){3,})[ ]*$` for `c` in `-_*`,
 * searched on every line of the block.
 */
export function findHorizontalRule(block) {
  for (const start of lineStarts(block)) {
    const end = lineEnd(block, start);
    let p = start;
    let indent = 0;
    while (p < end && block[p] === ' ' && indent < 3) { p++; indent++; }
    if (p < end && block[p] === ' ') continue;
    const ch = block[p];
    if (ch !== '-' && ch !== '_' && ch !== '*') continue;
    let count = 0;
    let ok = true;
    let q = p;
    let lastCharIndex = -1;
    while (q < end) {
      if (block[q] === ch) { count++; lastCharIndex = q; q++; continue; }
      if (block[q] === ' ') {
        let spaces = 0;
        while (q < end && block[q] === ' ') { q++; spaces++; }
        if (q >= end) break;             // trailing spaces are always allowed
        if (spaces > 2) { ok = false; break; }
        continue;
      }
      ok = false;
      break;
    }
    if (ok && count >= 3) {
      return { start, end, matchStart: p, matchEnd: end };
    }
  }
  return null;
}

/** `(^|\n)[ ]{0,3}>[ ]?(.*)` -> index of the `>` line start, or -1. */
export function findBlockQuote(block) {
  for (const start of lineStarts(block)) {
    let p = start;
    let indent = 0;
    while (block[p] === ' ' && indent < 3) { p++; indent++; }
    if (block[p] === '>') return start;
  }
  return -1;
}

function cleanQuoteLine(line) {
  if (pyStrip(line) === '>') return '';
  let p = 0;
  let indent = 0;
  while (line[p] === ' ' && indent < 3) { p++; indent++; }
  if (line[p] !== '>') return line;
  p++;
  if (line[p] === ' ') p++;
  return line.slice(p);
}

/* ------------------------------------------------------------- processors */

export class EmptyBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return !block || block.startsWith('\n');
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const filler = '\n\n';
    if (block) {
      block = block.slice(1);
      if (block) blocks.unshift(block);
    }
    const sibling = this.lastChild(parent);
    if (sibling !== null && sibling.tag === 'pre' && sibling.length &&
        sibling.at(0).tag === 'code') {
      const code = sibling.at(0);
      code.text = atomic(text0(code.text) + filler);
    }
  }
}

export class ListIndentProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.ITEM_TYPES = ['li'];
    this.LIST_TYPES = ['ul', 'ol'];
  }

  test(parent, block) {
    return block.startsWith(' '.repeat(this.tabLength)) &&
      !this.parser.state.isstate('detabbed') &&
      (this.ITEM_TYPES.includes(parent.tag) ||
        (parent.length && parent.at(-1) !== null &&
          this.LIST_TYPES.includes(parent.at(-1).tag)));
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const [level, sibling] = this.getLevel(parent, block);
    block = this.looseDetab(block, level);

    this.parser.state.set('detabbed');
    if (this.ITEM_TYPES.includes(parent.tag)) {
      this.parser.parseBlocks(parent, [block]);
    } else if (this.ITEM_TYPES.includes(sibling.tag)) {
      this.parser.parseBlocks(sibling, [block]);
    } else if (sibling.length && this.ITEM_TYPES.includes(sibling.at(-1).tag)) {
      this.parser.parseBlocks(sibling.at(-1), [block]);
    } else {
      this.createItem(sibling, block);
    }
    this.parser.state.reset();
  }

  createItem(parent, block) {
    const li = subElement(parent, 'li');
    this.parser.parseBlocks(li, [block]);
  }

  getLevel(parent, block) {
    let indentLevel = 0;
    let p = 0;
    while (matchAt(block, p, ' '.repeat(this.tabLength))) {
      p += this.tabLength;
      indentLevel += 1;
    }
    let level = this.parser.state.isstate('list') ? 1 : 0;
    let node = parent;
    while (indentLevel > level) {
      const child = this.lastChild(node);
      if (child !== null &&
        (this.LIST_TYPES.includes(child.tag) || this.ITEM_TYPES.includes(child.tag))) {
        if (this.LIST_TYPES.includes(child.tag)) level += 1;
        node = child;
      } else {
        break;
      }
    }
    return [level, node];
  }
}

export class CodeBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return block.startsWith(' '.repeat(this.tabLength));
  }

  run(parent, blocks) {
    const sibling = this.lastChild(parent);
    let block = blocks.shift();
    let theRest = '';
    if (sibling !== null && sibling.tag === 'pre' && sibling.length &&
        sibling.at(0).tag === 'code') {
      const code = sibling.at(0);
      [block, theRest] = this.detab(block);
      code.text = atomic(text0(code.text) + '\n' + codeEscape(pyRStrip(block)) + '\n');
    } else {
      const pre = subElement(parent, 'pre');
      const code = subElement(pre, 'code');
      [block, theRest] = this.detab(block);
      code.text = atomic(codeEscape(pyRStrip(block)) + '\n');
    }
    if (theRest) blocks.unshift(theRest);
  }
}

export class BlockQuoteProcessor extends BlockProcessor {
  test(parent, block) {
    return findBlockQuote(block) !== -1;
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const start = findBlockQuote(block);
    if (start !== -1) {
      const before = block.slice(0, start);
      this.parser.parseBlocks(parent, [before]);
      block = block.slice(start).split('\n').map(cleanQuoteLine).join('\n');
    }
    const sibling = this.lastChild(parent);
    let quote;
    if (sibling !== null && sibling.tag === 'blockquote') quote = sibling;
    else quote = subElement(parent, 'blockquote');

    this.parser.state.set('blockquote');
    this.parser.parseChunk(quote, block);
    this.parser.state.reset();
  }
}

export class OListProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.TAG = 'ol';
    this.STARTSWITH = '1';
    this.LAZY_OL = true;
    this.SIBLING_TAGS = ['ol', 'ul'];
  }

  /** `^[ ]{0,3}\d+\.[ ]+(.*)` */
  matchItem(line) {
    let p = 0;
    while (p < this.tabLength - 1 && line[p] === ' ') p++;
    let digits = 0;
    while (isAsciiDigit(line[p + digits])) digits++;
    if (digits === 0) return null;
    let q = p + digits;
    if (line[q] !== '.') return null;
    q++;
    let spaces = 0;
    while (line[q] === ' ') { q++; spaces++; }
    if (spaces === 0) return null;
    return { marker: line.slice(p, p + digits + 1), content: line.slice(q) };
  }

  /** `^[ ]{0,3}((\d+\.)|[*+-])[ ]+(.*)` */
  matchChild(line) {
    let p = 0;
    while (p < this.tabLength - 1 && line[p] === ' ') p++;
    let marker = null;
    let q = p;
    let digits = 0;
    while (isAsciiDigit(line[q + digits])) digits++;
    if (digits > 0 && line[q + digits] === '.') {
      marker = line.slice(q, q + digits + 1);
      q = q + digits + 1;
    } else if (line[q] === '*' || line[q] === '+' || line[q] === '-') {
      marker = line[q];
      q += 1;
    } else {
      return null;
    }
    let spaces = 0;
    while (line[q] === ' ') { q++; spaces++; }
    if (spaces === 0) return null;
    return { marker, content: line.slice(q) };
  }

  /** `^[ ]{tab,2*tab-1}((\d+\.)|[*+-])[ ]+.*` */
  matchIndented(line) {
    const indent = leadingSpaces(line);
    if (indent < this.tabLength || indent > this.tabLength * 2 - 1) return false;
    let q = indent;
    let digits = 0;
    while (isAsciiDigit(line[q + digits])) digits++;
    if (digits > 0 && line[q + digits] === '.') q = q + digits + 1;
    else if (line[q] === '*' || line[q] === '+' || line[q] === '-') q += 1;
    else return false;
    return line[q] === ' ';
  }

  test(parent, block) {
    return this.matchItem(block.split('\n')[0]) !== null && this.matchItem(block) !== null;
  }

  run(parent, blocks) {
    const items = this.getItems(blocks.shift());
    const sibling = this.lastChild(parent);
    let lst;

    if (sibling !== null && this.SIBLING_TAGS.includes(sibling.tag)) {
      lst = sibling;
      const last = lst.at(-1);
      if (text0(last.text)) {
        const p = new Element('p');
        p.text = last.text;
        last.text = '';
        last.insert(0, p);
      }
      const lch = this.lastChild(last);
      if (lch !== null && text0(lch.tail)) {
        const p = subElement(last, 'p');
        p.text = pyLStrip(text0(lch.tail));
        lch.tail = '';
      }
      const li = subElement(lst, 'li');
      this.parser.state.set('looselist');
      const firstitem = items.shift();
      this.parser.parseBlocks(li, [firstitem]);
      this.parser.state.reset();
    } else if (parent.tag === 'ol' || parent.tag === 'ul') {
      lst = parent;
    } else {
      lst = subElement(parent, this.TAG);
      if (!this.LAZY_OL && this.STARTSWITH !== '1') lst.set('start', this.STARTSWITH);
    }

    this.parser.state.set('list');
    for (const item of items) {
      if (item.startsWith(' '.repeat(this.tabLength))) {
        this.parser.parseBlocks(lst.at(-1), [item]);
      } else {
        const li = subElement(lst, 'li');
        this.parser.parseBlocks(li, [item]);
      }
    }
    this.parser.state.reset();
  }

  getItems(block) {
    const items = [];
    for (const line of block.split('\n')) {
      const m = this.matchChild(line);
      if (m) {
        if (items.length === 0 && this.TAG === 'ol') {
          let digits = '';
          for (const ch of m.marker) {
            if (isAsciiDigit(ch)) digits += ch;
            else break;
          }
          if (digits) this.STARTSWITH = digits;
        }
        items.push(m.content);
      } else if (this.matchIndented(line)) {
        if (items[items.length - 1].startsWith(' '.repeat(this.tabLength))) {
          items[items.length - 1] = items[items.length - 1] + '\n' + line;
        } else {
          items.push(line);
        }
      } else {
        items[items.length - 1] = items[items.length - 1] + '\n' + line;
      }
    }
    return items;
  }
}

export class UListProcessor extends OListProcessor {
  constructor(parser) {
    super(parser);
    this.TAG = 'ul';
  }

  /** `^[ ]{0,3}[*+-][ ]+(.*)` */
  matchItem(line) {
    let p = 0;
    while (p < this.tabLength - 1 && line[p] === ' ') p++;
    const ch = line[p];
    if (ch !== '*' && ch !== '+' && ch !== '-') return null;
    let q = p + 1;
    let spaces = 0;
    while (line[q] === ' ') { q++; spaces++; }
    if (spaces === 0) return null;
    return { marker: ch, content: line.slice(q) };
  }
}

export class HashHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return findHashHeader(block) !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const m = findHashHeader(block);
    if (m) {
      const before = block.slice(0, m.start);
      const after = block.slice(m.end);
      if (before) this.parser.parseBlocks(parent, [before]);
      const h = subElement(parent, 'h' + m.level);
      h.text = pyStrip(m.header);
      if (after) blocks.unshift(after);
    }
  }
}

export class SetextHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return matchSetextHeader(block);
  }

  run(parent, blocks) {
    const lines = blocks.shift().split('\n');
    const level = lines[1].startsWith('=') ? 1 : 2;
    const h = subElement(parent, 'h' + level);
    h.text = pyStrip(lines[0]);
    if (lines.length > 2) blocks.unshift(lines.slice(2).join('\n'));
  }
}

export class HRProcessor extends BlockProcessor {
  test(parent, block) {
    const m = findHorizontalRule(block);
    if (m) {
      this.match = m;
      return true;
    }
    return false;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const match = this.match;
    const prelines = rstripChars(block.slice(0, match.matchStart), '\n');
    if (prelines) this.parser.parseBlocks(parent, [prelines]);
    subElement(parent, 'hr');
    const postlines = lstripChars(block.slice(match.matchEnd), '\n');
    if (postlines) blocks.unshift(postlines);
  }
}

export class ReferenceProcessor extends BlockProcessor {
  test(parent, block) {
    return true;
  }

  /**
   * `^[ ]{0,3}\[([^\[\]]*)\]:[ ]*\n?[ ]*([^\s]+)[ ]*`
   * `(?:\n?[ ]*((["'])(.*)\4[ ]*|\((.*)\)[ ]*))?$`
   */
  matchReference(block) {
    for (const start of lineStarts(block)) {
      let p = start;
      let indent = 0;
      while (block[p] === ' ' && indent < 3) { p++; indent++; }
      if (block[p] !== '[') continue;
      let q = p + 1;
      while (q < block.length && block[q] !== '[' && block[q] !== ']') q++;
      if (block[q] !== ']') continue;
      const id = block.slice(p + 1, q);
      q++;
      if (block[q] !== ':') continue;
      q++;
      while (block[q] === ' ') q++;
      if (block[q] === '\n') q++;
      while (block[q] === ' ') q++;
      const linkStart = q;
      while (q < block.length && !isSpace(block[q])) q++;
      if (q === linkStart) continue;
      const link = block.slice(linkStart, q);
      while (block[q] === ' ') q++;

      let title = null;
      let end = q;
      if (q >= block.length || block[q] === '\n') {
        end = q;
      }
      // Optional title, possibly on the next line.
      let t = q;
      if (block[t] === '\n') t++;
      while (block[t] === ' ') t++;
      if (block[t] === '"' || block[t] === "'" || block[t] === '(') {
        const open = block[t];
        const close = open === '(' ? ')' : open;
        const lineStop = lineEnd(block, t);
        const closeIdx = block.lastIndexOf(close, lineStop);
        if (closeIdx > t) {
          let after = closeIdx + 1;
          while (block[after] === ' ') after++;
          if (after >= block.length || block[after] === '\n') {
            title = block.slice(t + 1, closeIdx);
            end = after;
          }
        }
      }
      if (title === null) {
        if (!(end >= block.length || block[end] === '\n')) continue;
      }
      return { start: p, end, id, link, title };
    }
    return null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const m = this.matchReference(block);
    if (m) {
      const id = pyStrip(m.id).toLowerCase();
      const link = rstripChars(lstripChars(m.link, '<'), '>');
      this.parser.md.references.set(id, [link, m.title]);
      const after = block.slice(m.end);
      if (pyStrip(after)) blocks.unshift(lstripChars(after, '\n'));
      const before = block.slice(0, m.start);
      if (pyStrip(before)) blocks.unshift(rstripChars(before, '\n'));
      return true;
    }
    blocks.unshift(block);
    return false;
  }
}

export class ParagraphProcessor extends BlockProcessor {
  test(parent, block) {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    if (pyStrip(block)) {
      if (this.parser.state.isstate('list')) {
        const sibling = this.lastChild(parent);
        if (sibling !== null) {
          if (text0(sibling.tail)) sibling.tail = text0(sibling.tail) + '\n' + block;
          else sibling.tail = '\n' + block;
        } else if (text0(parent.text)) {
          parent.text = text0(parent.text) + '\n' + block;
        } else {
          parent.text = pyLStrip(block);
        }
      } else {
        const p = subElement(parent, 'p');
        p.text = pyLStrip(block);
      }
    }
  }
}

export function buildBlockParser(md, BlockParserClass) {
  const parser = new BlockParserClass(md);
  parser.blockprocessors.register(new EmptyBlockProcessor(parser), 'empty', 100);
  parser.blockprocessors.register(new ListIndentProcessor(parser), 'indent', 90);
  parser.blockprocessors.register(new CodeBlockProcessor(parser), 'code', 80);
  parser.blockprocessors.register(new HashHeaderProcessor(parser), 'hashheader', 70);
  parser.blockprocessors.register(new SetextHeaderProcessor(parser), 'setextheader', 60);
  parser.blockprocessors.register(new HRProcessor(parser), 'hr', 50);
  parser.blockprocessors.register(new OListProcessor(parser), 'olist', 40);
  parser.blockprocessors.register(new UListProcessor(parser), 'ulist', 30);
  parser.blockprocessors.register(new BlockQuoteProcessor(parser), 'quote', 20);
  parser.blockprocessors.register(new ReferenceProcessor(parser), 'reference', 15);
  parser.blockprocessors.register(new ParagraphProcessor(parser), 'paragraph', 10);
  return parser;
}

