/**
 * Inline level processors.
 *
 * Each processor exposes `findFrom(data, from)` (the next candidate position,
 * equivalent to iterating matches of the reference pattern) and
 * `handleMatch(match, data)` which either builds a node or rejects the match.
 * All candidate detection is done with explicit character scanning.
 */

import { Element, atomic, isAtomic, str, text0 } from './element.mjs';
import { isSpace, isWordChar, isAsciiAlpha, isAsciiDigit, isHexDigit } from './chars.mjs';
import { pyStrip, matchAt, runLength } from './strings.mjs';
import { STX, ETX, AMP_SUBSTITUTE, INLINE_PLACEHOLDER_PREFIX } from './util.mjs';
import { codeEscape } from './blockprocessors.mjs';

export const ESCAPED_CHARS = ['\\', '`', '*', '_', '{', '}', '[', ']', '(', ')',
  '>', '#', '+', '-', '.', '!'];

/** HTML 4 entity names, used when obfuscating e-mail addresses. */
const CODEPOINT2NAME = new Map([
  [34, 'quot'], [38, 'amp'], [60, 'lt'], [62, 'gt'], [160, 'nbsp'],
  [169, 'copy'], [174, 'reg'], [8364, 'euro'], [163, 'pound'], [165, 'yen'],
  [162, 'cent'], [167, 'sect'], [176, 'deg'], [177, 'plusmn'], [215, 'times'],
  [247, 'divide']
]);

/* ------------------------------------------------------------------- base */

export class InlineProcessor {
  constructor(md) {
    this.md = md;
    this.ancestorExcludes = [];
  }

  /** Next candidate match at or after `from`, or null. */
  findFrom(data, from) {
    return null;
  }

  /** `{node, start, end}`; `start === null` rejects the match. */
  handleMatch(m, data) {
    return { node: null, start: null, end: null };
  }

  /** Replace inline placeholders by the text content they stand for. */
  unescape(text) {
    const stash = this.md.treeprocessors.get('inline').stashedNodes;
    if (!stash) return text;
    return substitutePlaceholders(text, (id) => {
      if (!stash.has(id)) return null;
      const value = stash.get(id);
      if (typeof value === 'string' || value instanceof String) return text0(value);
      return [...value.itertext()].map(text0).join('');
    });
  }
}

/** Walk `klzzwxh:NNNN` placeholders, replacing via `resolve`. */
export function substitutePlaceholders(text, resolve) {
  let out = '';
  let pos = 0;
  for (;;) {
    const idx = text.indexOf(INLINE_PLACEHOLDER_PREFIX, pos);
    if (idx === -1) return out + text.slice(pos);
    let p = idx + INLINE_PLACEHOLDER_PREFIX.length;
    let digits = '';
    while (p < text.length && isAsciiDigit(text[p])) { digits += text[p]; p++; }
    if (digits.length === 0 || text[p] !== ETX) {
      out += text.slice(pos, idx + INLINE_PLACEHOLDER_PREFIX.length);
      pos = idx + INLINE_PLACEHOLDER_PREFIX.length;
      continue;
    }
    const replacement = resolve(digits);
    out += text.slice(pos, idx) + (replacement === null || replacement === undefined ? '' : replacement);
    pos = p + 1;
  }
}

/** Replace `NN` escapes by `\` + the escaped character. */
export function backslashUnescape(text) {
  let out = '';
  let pos = 0;
  for (;;) {
    const idx = text.indexOf(STX, pos);
    if (idx === -1) return out + text.slice(pos);
    let p = idx + 1;
    let digits = '';
    while (p < text.length && isAsciiDigit(text[p])) { digits += text[p]; p++; }
    if (digits.length === 0 || text[p] !== ETX) {
      out += text.slice(pos, idx + 1);
      pos = idx + 1;
      continue;
    }
    out += text.slice(pos, idx) + '\\' + String.fromCodePoint(Number(digits));
    pos = p + 1;
  }
}

/** Replace `NN` escapes by the escaped character itself. */
export function unescapeEscapes(text) {
  let out = '';
  let pos = 0;
  for (;;) {
    const idx = text.indexOf(STX, pos);
    if (idx === -1) return out + text.slice(pos);
    let p = idx + 1;
    let digits = '';
    while (p < text.length && isAsciiDigit(text[p])) { digits += text[p]; p++; }
    if (digits.length === 0 || text[p] !== ETX) {
      out += text.slice(pos, idx + 1);
      pos = idx + 1;
      continue;
    }
    out += text.slice(pos, idx) + String.fromCodePoint(Number(digits));
    pos = p + 1;
  }
}

/* ------------------------------------------------------------- code spans */

export class BacktickInlineProcessor extends InlineProcessor {
  constructor(md) {
    super(md);
    this.ESCAPED_BSLASH = STX + '92' + ETX;
    this.tag = 'code';
  }

  findFrom(data, from) {
    for (let i = Math.max(0, from); i < data.length; i++) {
      if (data[i] === '\\') {
        if (i > 0 && data[i - 1] === '\\') continue;
        const n = runLength(data, i, '\\');
        if (n >= 2 && n % 2 === 0 && data[i + n] === '`') {
          return { start: i, end: i + n, groups: [data.slice(i, i + n), null, null] };
        }
        continue;
      }
      if (data[i] !== '`') continue;
      if (i > 0 && data[i - 1] === '\\') continue;
      const len = runLength(data, i, '`');
      const contentStart = i + len;
      for (let j = contentStart + 1; j + len <= data.length; j++) {
        if (data[j] !== '`') continue;
        if (data[j - 1] === '`') continue;
        if (runLength(data, j, '`') !== len) continue;
        if (data[j + len] === '`') continue;
        return {
          start: i,
          end: j + len,
          groups: [null, data.slice(i, contentStart), data.slice(contentStart, j)]
        };
      }
    }
    return null;
  }

  handleMatch(m, data) {
    if (m.groups[2] !== null) {
      const el = new Element(this.tag);
      el.text = atomic(codeEscape(pyStrip(m.groups[2])));
      return { node: el, start: m.start, end: m.end };
    }
    return {
      node: m.groups[0].split('\\\\').join(this.ESCAPED_BSLASH),
      start: m.start,
      end: m.end
    };
  }
}

/* ---------------------------------------------------------------- escapes */

export class EscapeInlineProcessor extends InlineProcessor {
  findFrom(data, from) {
    for (let i = Math.max(0, from); i < data.length - 1; i++) {
      if (data[i] === '\\') return { start: i, end: i + 2, groups: [data[i + 1]] };
    }
    return null;
  }

  handleMatch(m, data) {
    const char = m.groups[0];
    if (ESCAPED_CHARS.includes(char)) {
      return { node: STX + char.codePointAt(0) + ETX, start: m.start, end: m.end };
    }
    return { node: null, start: m.start, end: m.end };
  }
}

/* ------------------------------------------------------------------ links */

/** Content between `[` and the matching `]`. */
function getText(data, index) {
  let bracketCount = 1;
  let text = '';
  let pos = index;
  for (; pos < data.length; pos++) {
    const c = data[pos];
    if (c === ']') bracketCount -= 1;
    else if (c === '[') bracketCount += 1;
    index = pos + 1;
    if (bracketCount === 0) break;
    text += c;
  }
  return [text, index, bracketCount === 0];
}

function cleanTitle(title) {
  let out = '';
  for (const ch of title) out += isSpace(ch) ? ' ' : ch;
  return out;
}

export class LinkInlineProcessor extends InlineProcessor {
  constructor(md) {
    super(md);
    this.ancestorExcludes = ['a'];
  }

  /** `(?<!\!)\[` */
  findFrom(data, from) {
    for (let i = Math.max(0, from); i < data.length; i++) {
      if (data[i] === '[' && !(i > 0 && data[i - 1] === '!')) {
        return { start: i, end: i + 1, groups: [] };
      }
    }
    return null;
  }

  /**
   * Parse `(href "title")` starting at `index`, tracking nested parentheses.
   * Returns `[href, title, index, handled]`.
   */
  getLink(data, index) {
    if (data[index] !== '(') return ['', null, index, false];
    let pos = index + 1;
    while (pos < data.length && isSpace(data[pos])) pos++;

    // Empty destination: `[text]()`
    if (data[pos] === ')') return ['', null, pos + 1, true];

    let href = '';
    let title = null;

    if (data[pos] === '<') {
      const close = data.indexOf('>', pos + 1);
      const nextOpen = data.indexOf('<', pos + 1);
      if (close !== -1 && (nextOpen === -1 || nextOpen > close)) {
        href = pyStrip(data.slice(pos + 1, close));
        pos = close + 1;
      } else {
        return ['', null, index, false];
      }
    } else {
      let depth = 0;
      const start = pos;
      while (pos < data.length) {
        const c = data[pos];
        if (c === '\\' && pos + 1 < data.length) { pos += 2; continue; }
        if (isSpace(c)) break;
        if (c === '(') { depth += 1; pos += 1; continue; }
        if (c === ')') {
          if (depth === 0) break;
          depth -= 1;
          pos += 1;
          continue;
        }
        pos += 1;
      }
      href = data.slice(start, pos);
    }

    while (pos < data.length && isSpace(data[pos])) pos++;

    if (data[pos] === '"' || data[pos] === "'") {
      const quote = data[pos];
      let scan = pos + 1;
      let close = -1;
      while (scan < data.length) {
        if (data[scan] === '\\' && scan + 1 < data.length) { scan += 2; continue; }
        if (data[scan] === quote) {
          let after = scan + 1;
          while (after < data.length && isSpace(data[after])) after++;
          if (data[after] === ')') { close = scan; break; }
        }
        scan += 1;
      }
      if (close !== -1) {
        title = cleanTitle(this.unescape(data.slice(pos + 1, close)));
        pos = close + 1;
        while (pos < data.length && isSpace(data[pos])) pos++;
      }
    }

    if (data[pos] !== ')') return ['', null, index, false];
    return [href, title, pos + 1, true];
  }

  handleMatch(m, data) {
    const [text, afterText, handledText] = getText(data, m.end);
    if (!handledText) return { node: null, start: null, end: null };
    const [href, title, index, handled] = this.getLink(data, afterText);
    if (!handled) return { node: null, start: null, end: null };
    const el = new Element('a');
    el.text = text;
    el.set('href', href);
    if (title !== null) el.set('title', title);
    return { node: el, start: m.start, end: index };
  }
}

export class ImageInlineProcessor extends LinkInlineProcessor {
  constructor(md) {
    super(md);
    this.ancestorExcludes = [];
  }

  /** `\!\[` */
  findFrom(data, from) {
    for (let i = Math.max(0, from); i < data.length - 1; i++) {
      if (data[i] === '!' && data[i + 1] === '[') {
        return { start: i, end: i + 2, groups: [] };
      }
    }
    return null;
  }

  handleMatch(m, data) {
    const [text, afterText, handledText] = getText(data, m.end);
    if (!handledText) return { node: null, start: null, end: null };
    const [src, title, index, handled] = this.getLink(data, afterText);
    if (!handled) return { node: null, start: null, end: null };
    const el = new Element('img');
    el.set('src', src);
    if (title !== null) el.set('title', title);
    el.set('alt', this.unescape(text));
    return { node: el, start: m.start, end: index };
  }
}

export class ReferenceInlineProcessor extends LinkInlineProcessor {
  /** `\s?\[([^\]]*)\]` anchored at `index`. */
  evalId(data, index, text) {
    let p = index;
    if (p < data.length && isSpace(data[p])) p++;
    if (data[p] !== '[') return [null, index, false];
    let q = p + 1;
    while (q < data.length && data[q] !== ']') q++;
    if (q >= data.length) return [null, index, false];
    let id = data.slice(p + 1, q).toLowerCase();
    const end = q + 1;
    if (!id) id = text.toLowerCase();
    return [id, end, true];
  }

  makeTag(href, title, text) {
    const el = new Element('a');
    el.set('href', href);
    if (title) el.set('title', title);
    el.text = atomic(text);
    return el;
  }

  handleMatch(m, data) {
    const [text, afterText, handledText] = getText(data, m.end);
    if (!handledText) return { node: null, start: null, end: null };
    let [id, end, handled] = this.evalId(data, afterText, text);
    if (!handled) return { node: null, start: null, end: null };
    id = cleanNewlines(id);
    if (!this.md.references.has(id)) return { node: null, start: m.start, end };
    const [href, title] = this.md.references.get(id);
    return { node: this.makeTag(href, title, text), start: m.start, end };
  }
}

function cleanNewlines(text) {
  // `\s*\n\s*` -> a single space
  let out = '';
  let i = 0;
  while (i < text.length) {
    if (text[i] === '\n' || (isSpace(text[i]) && text.indexOf('\n', i) !== -1 &&
        allSpaceUntilNewline(text, i))) {
      let j = i;
      while (j < text.length && isSpace(text[j])) j++;
      out += ' ';
      i = j;
      continue;
    }
    out += text[i];
    i++;
  }
  return out;
}

function allSpaceUntilNewline(text, i) {
  let j = i;
  while (j < text.length && isSpace(text[j]) && text[j] !== '\n') j++;
  return text[j] === '\n';
}

export class ShortReferenceInlineProcessor extends ReferenceInlineProcessor {
  evalId(data, index, text) {
    return [text.toLowerCase(), index, true];
  }
}

export class ImageReferenceInlineProcessor extends ReferenceInlineProcessor {
  findFrom(data, from) {
    for (let i = Math.max(0, from); i < data.length - 1; i++) {
      if (data[i] === '!' && data[i + 1] === '[') {
        return { start: i, end: i + 2, groups: [] };
      }
    }
    return null;
  }

  makeTag(href, title, text) {
    const el = new Element('img');
    el.set('src', href);
    if (title) el.set('title', title);
    el.set('alt', this.unescape(text));
    return el;
  }
}

export class ShortImageReferenceInlineProcessor extends ImageReferenceInlineProcessor {
  evalId(data, index, text) {
    return [text.toLowerCase(), index, true];
  }
}

/* -------------------------------------------------------------- autolinks */

export class AutolinkInlineProcessor extends InlineProcessor {
  /** `<((?:[Ff]|[Hh][Tt])[Tt][Pp][Ss]?://[^<>]*)>` */
  findFrom(data, from) {
    for (let i = Math.max(0, from); i < data.length; i++) {
      if (data[i] !== '<') continue;
      let p = i + 1;
      const lower = data.slice(p, p + 6).toLowerCase();
      let scheme = null;
      if (lower.startsWith('http')) scheme = 4;
      else if (lower.startsWith('ftp')) scheme = 3;
      else continue;
      p += scheme;
      if (data[p] === 's' || data[p] === 'S') p++;
      if (data.slice(p, p + 3) !== '://') continue;
      p += 3;
      let q = p;
      while (q < data.length && data[q] !== '<' && data[q] !== '>') q++;
      if (data[q] !== '>') continue;
      return { start: i, end: q + 1, groups: [data.slice(i + 1, q)] };
    }
    return null;
  }

  handleMatch(m, data) {
    const el = new Element('a');
    el.set('href', this.unescape(m.groups[0]));
    el.text = atomic(m.groups[0]);
    return { node: el, start: m.start, end: m.end };
  }
}

export class AutomailInlineProcessor extends InlineProcessor {
  /** `<([^<> !]*@[^@<> ]*)>` */
  findFrom(data, from) {
    for (let i = Math.max(0, from); i < data.length; i++) {
      if (data[i] !== '<') continue;
      let p = i + 1;
      while (p < data.length && data[p] !== '<' && data[p] !== '>' && data[p] !== ' ' &&
        data[p] !== '!') p++;
      if (data[p] !== '@') continue;
      let q = p + 1;
      while (q < data.length && data[q] !== '@' && data[q] !== '<' && data[q] !== '>' &&
        data[q] !== ' ') q++;
      if (data[q] !== '>') continue;
      return { start: i, end: q + 1, groups: [data.slice(i + 1, q)] };
    }
    return null;
  }

  handleMatch(m, data) {
    const el = new Element('a');
    let email = this.unescape(m.groups[0]);
    if (email.startsWith('mailto:')) email = email.slice('mailto:'.length);

    const encode = (code) => {
      const name = CODEPOINT2NAME.get(code);
      return name ? AMP_SUBSTITUTE + name + ';' : AMP_SUBSTITUTE + '#' + code + ';';
    };

    let letters = '';
    for (const ch of email) letters += encode(ch.codePointAt(0));
    el.text = atomic(letters);

    let mailto = '';
    for (const ch of 'mailto:' + email) mailto += AMP_SUBSTITUTE + '#' + ch.codePointAt(0) + ';';
    el.set('href', mailto);
    return { node: el, start: m.start, end: m.end };
  }
}

/* ------------------------------------------------------- breaks, raw html */

export class SubstituteTagInlineProcessor extends InlineProcessor {
  constructor(md, tag) {
    super(md);
    this.tag = tag;
  }

  /** `  \n` */
  findFrom(data, from) {
    for (let i = Math.max(0, from); i + 2 < data.length + 1; i++) {
      if (data[i] === ' ' && data[i + 1] === ' ' && data[i + 2] === '\n') {
        return { start: i, end: i + 3, groups: [] };
      }
    }
    return null;
  }

  handleMatch(m, data) {
    return { node: new Element(this.tag), start: m.start, end: m.end };
  }
}

export class HtmlInlineProcessor extends InlineProcessor {
  /** `(<(\/?[a-zA-Z][^<>]*|!--(?:(?!<!--|-->).)*--)>)` */
  findFrom(data, from) {
    for (let i = Math.max(0, from); i < data.length; i++) {
      if (data[i] !== '<') continue;
      let p = i + 1;
      if (data[p] === '!' && data[p + 1] === '-' && data[p + 2] === '-') {
        let q = p + 3;
        for (;;) {
          if (q >= data.length) { q = -1; break; }
          if (matchAt(data, q, '<!--')) { q = -1; break; }
          if (matchAt(data, q, '-->')) break;
          q++;
        }
        if (q === -1) continue;
        // `-->` closes the comment: `--` belongs to the pattern, `>` ends it.
        return { start: i, end: q + 3, groups: [data.slice(i, q + 3)] };
      }
      if (data[p] === '/') p++;
      if (!isAsciiAlpha(data[p])) continue;
      let q = p;
      while (q < data.length && data[q] !== '<' && data[q] !== '>') q++;
      if (data[q] !== '>') continue;
      return { start: i, end: q + 1, groups: [data.slice(i, q + 1)] };
    }
    return null;
  }

  serializeStashed(text) {
    const stash = this.md.treeprocessors.get('inline').stashedNodes;
    return substitutePlaceholders(text, (id) => {
      if (!stash || !stash.has(id)) return null;
      const value = stash.get(id);
      if (typeof value === 'string' || value instanceof String) return text0(value);
      return this.md.serializer(value);
    });
  }

  handleMatch(m, data) {
    const rawhtml = backslashUnescape(this.serializeStashed(m.groups[0]));
    const placeholder = this.md.htmlStash.store(rawhtml);
    return { node: placeholder, start: m.start, end: m.end };
  }
}

export class EntityInlineProcessor extends HtmlInlineProcessor {
  /** `(&(?:\#[0-9]+|\#x[0-9a-fA-F]+|[a-zA-Z0-9]+);)` */
  findFrom(data, from) {
    for (let i = Math.max(0, from); i < data.length; i++) {
      if (data[i] !== '&') continue;
      let p = i + 1;
      if (data[p] === '#') {
        p++;
        if (data[p] === 'x') {
          p++;
          let n = 0;
          while (p < data.length && isHexDigit(data[p])) { p++; n++; }
          if (n === 0) continue;
        } else {
          let n = 0;
          while (p < data.length && isAsciiDigit(data[p])) { p++; n++; }
          if (n === 0) continue;
        }
      } else {
        let n = 0;
        while (p < data.length && (isAsciiAlpha(data[p]) || isAsciiDigit(data[p]))) { p++; n++; }
        if (n === 0) continue;
      }
      if (data[p] !== ';') continue;
      return { start: i, end: p + 1, groups: [data.slice(i, p + 1)] };
    }
    return null;
  }
}

/* --------------------------------------------------------- not-strong text */

export class SimpleTextInlineProcessor extends InlineProcessor {
  /** `((^|\s)(\*|_)(\s|$))` */
  findFrom(data, from) {
    const n = data.length;
    const atEnd = (i) => i >= n || (i === n - 1 && data[n - 1] === '\n');
    for (let i = Math.max(0, from); i < n; i++) {
      if (i === 0 && (data[0] === '*' || data[0] === '_')) {
        if (isSpace(data[1])) return { start: 0, end: 2, groups: [data.slice(0, 2)] };
        if (atEnd(1)) return { start: 0, end: 1, groups: [data.slice(0, 1)] };
      }
      if (!isSpace(data[i])) continue;
      const c = data[i + 1];
      if (c !== '*' && c !== '_') continue;
      if (isSpace(data[i + 2])) {
        return { start: i, end: i + 3, groups: [data.slice(i, i + 3)] };
      }
      if (atEnd(i + 2)) {
        return { start: i, end: i + 2, groups: [data.slice(i, i + 2)] };
      }
    }
    return null;
  }

  handleMatch(m, data) {
    return { node: m.groups[0], start: m.start, end: m.end };
  }
}

/* ------------------------------------------------------ emphasis / strong */

/**
 * Matchers for the emphasis/strong patterns, all anchored at `pos`.
 * Each returns `{start, end, groups:[token, g2, g3]}` or null.
 */
function lazyFind(data, from, test) {
  for (let i = from; i <= data.length; i++) {
    const r = test(i);
    if (r) return r;
  }
  return null;
}

/** `(c)\1{2}(.+?)\1(.*?)\1{2}` -> `<strong><em>` */
function matchEmStrong(data, pos, c) {
  if (!matchAt(data, pos, c.repeat(3))) return null;
  const contentStart = pos + 3;
  for (let i = contentStart + 1; i < data.length; i++) {
    if (data[i] !== c) continue;
    for (let j = i + 1; j + 2 <= data.length; j++) {
      if (data[j] === c && data[j + 1] === c) {
        return {
          start: pos,
          end: j + 2,
          groups: [c, data.slice(contentStart, i), data.slice(i + 1, j)]
        };
      }
    }
  }
  return null;
}

/** `(c)\1{2}(.+?)\1{2}(.*?)\1` -> `<em><strong>` */
function matchStrongEm(data, pos, c) {
  if (!matchAt(data, pos, c.repeat(3))) return null;
  const contentStart = pos + 3;
  for (let i = contentStart + 1; i + 2 <= data.length; i++) {
    if (!(data[i] === c && data[i + 1] === c)) continue;
    for (let j = i + 2; j < data.length; j++) {
      if (data[j] === c) {
        return {
          start: pos,
          end: j + 1,
          groups: [c, data.slice(contentStart, i), data.slice(i + 2, j)]
        };
      }
    }
  }
  return null;
}

/** `(c)\1(?!\1)([^c]+?)\1(?!\1)(.+?)\1{3}` -> `<strong>text<em>text</em></strong>` */
function matchStrongEm3(data, pos, c) {
  if (!matchAt(data, pos, c.repeat(2))) return null;
  if (data[pos + 2] === c) return null;
  const contentStart = pos + 2;
  for (let i = contentStart + 1; i < data.length; i++) {
    if (data[i] !== c) {
      if (data[i] === c) break;
      continue;
    }
    if (data.slice(contentStart, i).indexOf(c) !== -1) break;
    if (data[i + 1] === c) continue;
    for (let j = i + 2; j + 3 <= data.length; j++) {
      if (matchAt(data, j, c.repeat(3))) {
        return {
          start: pos,
          end: j + 3,
          groups: [c, data.slice(contentStart, i), data.slice(i + 1, j)]
        };
      }
    }
  }
  return null;
}

/** `(c{2})(.+?)\1` -> `<strong>` */
function matchStrong(data, pos, c) {
  if (!matchAt(data, pos, c.repeat(2))) return null;
  const contentStart = pos + 2;
  for (let i = contentStart + 1; i + 2 <= data.length; i++) {
    if (data[i] === c && data[i + 1] === c) {
      return { start: pos, end: i + 2, groups: [c + c, data.slice(contentStart, i)] };
    }
  }
  return null;
}

/** `(c)([^c]+)\1` -> `<em>` */
function matchEmphasis(data, pos, c) {
  if (data[pos] !== c) return null;
  let i = pos + 1;
  while (i < data.length && data[i] !== c) i++;
  if (i === pos + 1) return null;
  if (data[i] !== c) return null;
  return { start: pos, end: i + 1, groups: [c, data.slice(pos + 1, i)] };
}

const notWord = (ch) => ch === undefined || !isWordChar(ch);

/** `(?<!\w)(c{2})(?!c)(.+?)(?<!c)\1(?!\w)` */
function matchSmartStrong(data, pos, c) {
  if (!notWord(data[pos - 1])) return null;
  if (!matchAt(data, pos, c.repeat(2))) return null;
  if (data[pos + 2] === c) return null;
  const contentStart = pos + 2;
  for (let i = contentStart + 1; i + 2 <= data.length; i++) {
    if (!(data[i] === c && data[i + 1] === c)) continue;
    if (data[i - 1] === c) continue;
    if (!notWord(data[i + 2])) continue;
    return { start: pos, end: i + 2, groups: [c + c, data.slice(contentStart, i)] };
  }
  return null;
}

/** `(?<!\w)(c)(?!c)(.+?)(?<!c)\1(?!\w)` */
function matchSmartEmphasis(data, pos, c) {
  if (!notWord(data[pos - 1])) return null;
  if (data[pos] !== c) return null;
  if (data[pos + 1] === c) return null;
  const contentStart = pos + 1;
  for (let i = contentStart + 1; i < data.length; i++) {
    if (data[i] !== c) continue;
    if (data[i - 1] === c) continue;
    if (!notWord(data[i + 1])) continue;
    return { start: pos, end: i + 1, groups: [c, data.slice(contentStart, i)] };
  }
  return null;
}

/** `(?<!\w)(c)\1(?!\1)(.+?)(?<!\w)\1(?!\1)(.+?)\1{3}(?!\w)` */
function matchSmartStrongEm(data, pos, c) {
  if (!notWord(data[pos - 1])) return null;
  if (!matchAt(data, pos, c.repeat(2))) return null;
  if (data[pos + 2] === c) return null;
  const contentStart = pos + 2;
  for (let i = contentStart + 1; i < data.length; i++) {
    if (data[i] !== c) continue;
    if (!notWord(data[i - 1])) continue;
    if (data[i + 1] === c) continue;
    for (let j = i + 2; j + 3 <= data.length; j++) {
      if (matchAt(data, j, c.repeat(3)) && notWord(data[j + 3])) {
        return {
          start: pos,
          end: j + 3,
          groups: [c, data.slice(contentStart, i), data.slice(i + 1, j)]
        };
      }
    }
  }
  return null;
}

class EmStrongProcessor extends InlineProcessor {
  constructor(md, token, patterns) {
    super(md);
    this.token = token;
    this.PATTERNS = patterns;
  }

  findFrom(data, from) {
    for (let i = Math.max(0, from); i < data.length; i++) {
      if (data[i] === this.token) return { start: i, end: i + 1, groups: [] };
    }
    return null;
  }

  buildElement(m, builder, tags, index) {
    if (builder === 'double2') return this.buildDouble2(m, tags, index);
    if (builder === 'double') return this.buildDouble(m, tags, index);
    return this.buildSingle(m, tags, index);
  }

  buildSingle(m, tag, idx) {
    const el1 = new Element(tag);
    this.parseSubPatterns(m.groups[1], el1, null, idx);
    return el1;
  }

  buildDouble(m, tags, idx) {
    const [tag1, tag2] = tags.split(',');
    const el1 = new Element(tag1);
    const el2 = new Element(tag2);
    this.parseSubPatterns(m.groups[1], el2, null, idx);
    el1.append(el2);
    this.parseSubPatterns(m.groups[2], el1, el2, idx);
    return el1;
  }

  buildDouble2(m, tags, idx) {
    const [tag1, tag2] = tags.split(',');
    const el1 = new Element(tag1);
    const el2 = new Element(tag2);
    this.parseSubPatterns(m.groups[1], el1, null, idx);
    this.parseSubPatterns(m.groups[2], el2, null, idx);
    el1.append(el2);
    return el1;
  }

  parseSubPatterns(data, parent, last, idx) {
    let offset = 0;
    let pos = 0;
    const length = data.length;
    while (pos < length) {
      if (data[pos] === this.token) {
        let matched = false;
        for (let index = 0; index < this.PATTERNS.length; index++) {
          if (index <= idx) continue;
          const item = this.PATTERNS[index];
          const m = item.match(data, pos, this.token);
          if (m) {
            const el = this.buildElement(m, item.builder, item.tags, index);
            if (last) last.tail = data.slice(offset, pos);
            else if (text0(parent.text)) parent.text = text0(parent.text) + data.slice(offset, pos);
            else parent.text = data.slice(offset, pos);
            parent.append(el);
            last = el;
            offset = m.end;
            pos = m.end;
            matched = true;
          }
        }
        if (!matched) pos += 1;
      } else {
        pos += 1;
      }
    }
    if (last) last.tail = data.slice(offset);
    else if (text0(parent.text)) parent.text = text0(parent.text) + data.slice(offset);
    else parent.text = data.slice(offset);
  }

  handleMatch(m, data) {
    for (let index = 0; index < this.PATTERNS.length; index++) {
      const item = this.PATTERNS[index];
      const m1 = item.match(data, m.start, this.token);
      if (m1) {
        return {
          node: this.buildElement(m1, item.builder, item.tags, index),
          start: m1.start,
          end: m1.end
        };
      }
    }
    return { node: null, start: null, end: null };
  }
}

export class AsteriskProcessor extends EmStrongProcessor {
  constructor(md) {
    super(md, '*', [
      { match: matchEmStrong, builder: 'double', tags: 'strong,em' },
      { match: matchStrongEm, builder: 'double', tags: 'em,strong' },
      { match: matchStrongEm3, builder: 'double2', tags: 'strong,em' },
      { match: matchStrong, builder: 'single', tags: 'strong' },
      { match: matchEmphasis, builder: 'single', tags: 'em' }
    ]);
  }
}

export class UnderscoreProcessor extends EmStrongProcessor {
  constructor(md) {
    super(md, '_', [
      { match: matchEmStrong, builder: 'double', tags: 'strong,em' },
      { match: matchStrongEm, builder: 'double', tags: 'em,strong' },
      { match: matchSmartStrongEm, builder: 'double2', tags: 'strong,em' },
      { match: matchSmartStrong, builder: 'single', tags: 'strong' },
      { match: matchSmartEmphasis, builder: 'single', tags: 'em' }
    ]);
  }
}

/* --------------------------------------------------------------- registry */

export function buildInlinePatterns(md, Registry) {
  const patterns = new Registry();
  patterns.register(new BacktickInlineProcessor(md), 'backtick', 190);
  patterns.register(new EscapeInlineProcessor(md), 'escape', 180);
  patterns.register(new ReferenceInlineProcessor(md), 'reference', 170);
  patterns.register(new LinkInlineProcessor(md), 'link', 160);
  patterns.register(new ImageInlineProcessor(md), 'image_link', 150);
  patterns.register(new ImageReferenceInlineProcessor(md), 'image_reference', 140);
  patterns.register(new ShortReferenceInlineProcessor(md), 'short_reference', 130);
  patterns.register(new ShortImageReferenceInlineProcessor(md), 'short_image_ref', 125);
  patterns.register(new AutolinkInlineProcessor(md), 'autolink', 120);
  patterns.register(new AutomailInlineProcessor(md), 'automail', 110);
  patterns.register(new SubstituteTagInlineProcessor(md, 'br'), 'linebreak', 100);
  patterns.register(new HtmlInlineProcessor(md), 'html', 90);
  patterns.register(new EntityInlineProcessor(md), 'entity', 80);
  patterns.register(new SimpleTextInlineProcessor(md), 'not_strong', 70);
  patterns.register(new AsteriskProcessor(md), 'em_strong', 60);
  patterns.register(new UnderscoreProcessor(md), 'em_strong2', 50);
  return patterns;
}

